1	//! Self-model persistence and lifecycle (spec-adlc-thoth §3.1, §7.1, §8.5,
2	//! slice 1.0 + 1.5).
3	//!
4	//! Layout under `<root>/.sea-forge/self-model/`:
5	//!   manifest.json                     — installation manifest (release, current
6	//!                                        snapshot id, staleness); the lifecycle
7	//!                                        discriminator, never an immutable record.
8	//!   realization/release.json          — release realization (verified, not regenerated).
9	//!   realization/cell.json             — cell realization (rebuildable).
10	//!   snapshots/<snapshot_id>.json      — immutable SelfModelSnapshot records.
11	//!   projections/<kind>/...            — rebuildable KG/CALM/JSON projections.
12	//!
13	//! Init/upgrade is detected by the manifest's release_id/schema_version. Upgrade
14	//! never rewrites prior snapshots. Extension mutations mark the current snapshot
15	//! stale via the manifest and request a rebuild; immutable snapshot files are
16	//! never mutated. A failed rebuild preserves the prior verifiable snapshot.
17	
18	use crate::projections::{project_self, verify_projection, SelfModelProjection};
19	use crate::{
20	    build_cell_realization, build_snapshot, bundled, load_composed, release_realization,
21	    verify_bundled, verify_snapshot, CellRealization, ExtensionState, ReleaseRealization,
22	    SelfModelSnapshot, SnapshotFreshness, ToolchainProbe, KERNEL_VERSION, RELEASE_ID,
23	};
24	use sea_forge_core::errors::ForgeError;
25	use serde::{Deserialize, Serialize};
26	use std::fs;
27	use std::path::{Path, PathBuf};
28	
29	const SCHEMA_VERSION: &str = "self_model.v1";
30	
31	fn dir(root: &Path) -> PathBuf {
32	    root.join(".sea-forge").join("self-model")
33	}
34	fn snapshots_dir(root: &Path) -> PathBuf {
35	    dir(root).join("snapshots")
36	}
37	fn projections_dir(root: &Path) -> PathBuf {
38	    dir(root).join("projections")
39	}
40	fn realization_dir(root: &Path) -> PathBuf {
41	    dir(root).join("realization")
42	}
43	fn manifest_path(root: &Path) -> PathBuf {
44	    dir(root).join("manifest.json")
45	}
46	fn snapshot_path(root: &Path, snapshot_id: &str) -> PathBuf {
47	    snapshots_dir(root).join(format!("{snapshot_id}.json"))
48	}
49	
50	#[derive(Clone, Debug, Serialize, Deserialize)]
51	pub struct SelfModelManifest {
52	    pub schema_version: String,
53	    pub release_id: String,
54	    pub kernel_version: String,
55	    pub current_snapshot_id: Option<String>,
56	    #[serde(default)]
57	    pub stale: bool,
58	    #[serde(default, skip_serializing_if = "Option::is_none")]
59	    pub stale_reason: Option<String>,
60	    pub initialized_at: String,
61	}
62	
63	/// Inputs for a snapshot rebuild. The caller (CLI/server) supplies extension
64	/// state, environment contracts, and EVIDENCED probe results; the store never
65	/// executes probes itself (spec-adlc-thoth §7.2, slice 1.4).
66	#[derive(Clone, Debug, Default)]
67	pub struct RebuildInputs<'a> {
68	    pub cell_id: &'a str,
69	    pub active_extensions: Vec<ExtensionState>,
70	    pub environments_present: Vec<String>,
71	    pub probes: Vec<ToolchainProbe>,
72	    pub sandbox_classes_available: Vec<String>,
73	    pub created_at: &'a str,
74	    pub capability_projection_sha256: &'a str,
75	}
76	
77	fn read_manifest(root: &Path) -> Result<Option<SelfModelManifest>, ForgeError> {
78	    let path = manifest_path(root);
79	    if !path.exists() {
80	        return Ok(None);
81	    }
82	    let bytes = fs::read(&path).map_err(|e| ForgeError::io("read self-model manifest", e))?;
83	    let manifest: SelfModelManifest = serde_json::from_slice(&bytes)
84	        .map_err(|e| ForgeError::SelfModel(format!("self_model_error: bad manifest: {e}")))?;
85	    Ok(Some(manifest))
86	}
87	
88	fn write_manifest(root: &Path, manifest: &SelfModelManifest) -> Result<(), ForgeError> {
89	    let path = manifest_path(root);
90	    fs::create_dir_all(path.parent().unwrap_or(Path::new(".")))
91	        .map_err(|e| ForgeError::io("create self-model dir", e))?;
92	    let bytes = serde_json::to_vec_pretty(manifest)?;
93	    let tmp = path.with_extension("tmp");
94	    fs::write(&tmp, &bytes).map_err(|e| ForgeError::io("write manifest tmp", e))?;
95	    fs::rename(&tmp, &path).map_err(|e| ForgeError::io("rename manifest", e))?;
96	    Ok(())
97	}
98	
99	fn write_immutable<T: Serialize>(path: &Path, value: &T) -> Result<(), ForgeError> {
100	    if path.exists() {
101	        // Immutable records are never overwritten; a same-id collision is integrity error.
102	        return Err(ForgeError::SelfModel(format!(
103	            "self_model_error: immutable record already exists: {}",
104	            path.display()
105	        )));
106	    }
107	    if let Some(parent) = path.parent() {
108	        fs::create_dir_all(parent).map_err(|e| ForgeError::io("create record parent", e))?;
109	    }
110	    let bytes = serde_json::to_vec_pretty(value)?;
111	    let tmp = path.with_extension("tmp");
112	    fs::write(&tmp, &bytes).map_err(|e| ForgeError::io("write record tmp", e))?;
113	    fs::rename(&tmp, path).map_err(|e| ForgeError::io("rename record", e))?;
114	    Ok(())
115	}
116	
117	fn write_realization(
118	    root: &Path,
119	    release: &ReleaseRealization,
120	    cell: &CellRealization,
121	) -> Result<(), ForgeError> {
122	    let rdir = realization_dir(root);
123	    fs::create_dir_all(&rdir).map_err(|e| ForgeError::io("create realization dir", e))?;
124	    let rpath = rdir.join("release.json");
125	    let bytes = serde_json::to_vec_pretty(release)?;
126	    let tmp = rpath.with_extension("tmp");
127	    fs::write(&tmp, &bytes).map_err(|e| ForgeError::io("write release realization tmp", e))?;
128	    fs::rename(&tmp, &rpath).map_err(|e| ForgeError::io("rename release realization", e))?;
129	    let cpath = rdir.join("cell.json");
130	    let bytes = serde_json::to_vec_pretty(cell)?;
131	    let tmp = cpath.with_extension("tmp");
132	    fs::write(&tmp, &bytes).map_err(|e| ForgeError::io("write cell realization tmp", e))?;
133	    fs::rename(&tmp, &cpath).map_err(|e| ForgeError::io("rename cell realization", e))?;
134	    Ok(())
135	}
136	
137	/// Read the persisted cell realization (rebuildable projection of registry+probes).
138	pub fn read_cell_realization(root: &Path) -> Result<Option<CellRealization>, ForgeError> {
139	    let path = realization_dir(root).join("cell.json");
140	    if !path.exists() {
141	        return Ok(None);
142	    }
143	    let bytes = fs::read(&path).map_err(|e| ForgeError::io("read cell realization", e))?;
144	    let cell: CellRealization = serde_json::from_slice(&bytes).map_err(|e| {
145	        ForgeError::SelfModel(format!("self_model_error: bad cell realization: {e}"))
146	    })?;
147	    Ok(Some(cell))
148	}
149	
150	pub fn read_release_realization(root: &Path) -> Result<Option<ReleaseRealization>, ForgeError> {
151	    let path = realization_dir(root).join("release.json");
152	    if !path.exists() {
153	        return Ok(None);
154	    }
155	    let bytes = fs::read(&path).map_err(|e| ForgeError::io("read release realization", e))?;
156	    let r: ReleaseRealization = serde_json::from_slice(&bytes).map_err(|e| {
157	        ForgeError::SelfModel(format!("self_model_error: bad release realization: {e}"))
158	    })?;
159	    Ok(Some(r))
160	}
161	
162	fn materialize_projections(
163	    root: &Path,
164	    projections: &[SelfModelProjection],
165	) -> Result<(), ForgeError> {
166	    let pdir = projections_dir(root);
167	    // Clear prior projection outputs so a wrong-hash pre-generated file is
168	    // regenerated, not trusted (spec §10.1, T9.3).
169	    if pdir.exists() {
170	        fs::remove_dir_all(&pdir).map_err(|e| ForgeError::io("clear projections dir", e))?;
171	    }
172	    fs::create_dir_all(&pdir).map_err(|e| ForgeError::io("create projections dir", e))?;
173	    for proj in projections {
174	        // Write the ProjectionRecord alongside its outputs.
175	        let kind_label = match proj.record.projection_kind {
176	            sea_forge_core::types::ProjectionKind::Kg => "kg",
177	            sea_forge_core::types::ProjectionKind::Calm => "calm",
178	            sea_forge_core::types::ProjectionKind::SelfModelSnapshot => "self_model_snapshot",
179	            _ => continue,
180	        };
181	        let kind_dir = pdir.join(kind_label);
182	        fs::create_dir_all(&kind_dir)
183	            .map_err(|e| ForgeError::io("create projection kind dir", e))?;
184	        for (path, content) in &proj.outputs {
185	            let full = pdir.join(path);
186	            if let Some(parent) = full.parent() {
187	                fs::create_dir_all(parent)
188	                    .map_err(|e| ForgeError::io("create projection output parent", e))?;
189	            }
190	            fs::write(&full, content).map_err(|e| ForgeError::io("write projection output", e))?;
191	        }
192	        let record_path = kind_dir.join("projection-record.json");
193	        let bytes = serde_json::to_vec_pretty(&proj.record)?;
194	        fs::write(&record_path, bytes).map_err(|e| ForgeError::io("write projection record", e))?;
195	    }
196	    Ok(())
197	}
198	
199	fn assemble(
200	    root: &Path,
201	    inputs: &RebuildInputs<'_>,
202	) -> Result<(SelfModelSnapshot, Vec<SelfModelProjection>, CellRealization), ForgeError> {
203	    let _ = root;
204	    let models = bundled();
205	    verify_bundled(&models)?;
206	    let composed = load_composed(&models)?;
207	    let release = release_realization();
208	    let cell = build_cell_realization(
209	        inputs.cell_id,
210	        inputs.active_extensions.clone(),
211	        inputs.environments_present.clone(),
212	        inputs.probes.clone(),
213	        inputs.sandbox_classes_available.clone(),
214	        inputs.created_at,
215	    );
216	    let snapshot = build_snapshot(
217	        &composed,
218	        &release,
219	        &cell,
220	        inputs.capability_projection_sha256,
221	        inputs.created_at,
222	    )?;
223	    let projections = project_self(&composed, &snapshot, inputs.created_at)?;
224	    Ok((snapshot, projections, cell))
225	}
226	
227	/// Build a fresh snapshot and commit it: writes projections, realization, the
228	/// immutable snapshot record, and updates the manifest (current=new, stale=false).
229	/// On any failure the prior snapshot remains verifiable (failure atomicity).
230	pub fn rebuild(root: &Path, inputs: &RebuildInputs<'_>) -> Result<SelfModelSnapshot, ForgeError> {
231	    fs::create_dir_all(snapshots_dir(root))
232	        .map_err(|e| ForgeError::io("create snapshots dir", e))?;
233	    let (snapshot, projections, cell) = assemble(root, inputs)?;
234	
235	    // Commit order: projections + realization first, then the immutable snapshot,
236	    // then the manifest pointer. A failure before the manifest write leaves the
237	    // prior current snapshot authoritative.
238	    materialize_projections(root, &projections)?;
239	    let release = release_realization();
240	    write_realization(root, &release, &cell)?;
241	    write_immutable(&snapshot_path(root, &snapshot.snapshot_id), &snapshot)?;
242	
243	    let manifest = SelfModelManifest {
244	        schema_version: SCHEMA_VERSION.into(),
245	        release_id: RELEASE_ID.into(),
246	        kernel_version: KERNEL_VERSION.into(),
247	        current_snapshot_id: Some(snapshot.snapshot_id.clone()),
248	        stale: false,
249	        stale_reason: None,
250	        initialized_at: inputs.created_at.to_string(),
251	    };
252	    write_manifest(root, &manifest)?;
253	    Ok(snapshot)
254	}
255	
256	/// First-root initialization: if no manifest exists, build the initial snapshot.
257	/// If a manifest exists for the same release, return the current snapshot. A
258	/// release-id change is an upgrade (builds a new snapshot; prior ones remain).
259	pub fn ensure_init(
260	    root: &Path,
261	    inputs: &RebuildInputs<'_>,
262	) -> Result<SelfModelSnapshot, ForgeError> {
263	    if let Some(manifest) = read_manifest(root)? {
264	        if manifest.release_id == RELEASE_ID
265	            && manifest.schema_version == SCHEMA_VERSION
266	            && manifest.current_snapshot_id.is_some()
267	        {
268	            return current_snapshot(root)?.ok_or_else(|| {
269	                ForgeError::SelfModel(
270	                    "self_model_error: manifest names a missing current snapshot".into(),
271	                )
272	            });
273	        }
274	        // Release/schema change ⇒ upgrade: rebuild (never rewrite prior snapshots).
275	    }
276	    rebuild(root, inputs)
277	}
278	
279	/// The current (newest committed) snapshot, or None if uninitialized.
280	pub fn current_snapshot(root: &Path) -> Result<Option<SelfModelSnapshot>, ForgeError> {
281	    let Some(manifest) = read_manifest(root)? else {
282	        return Ok(None);
283	    };
284	    let Some(sid) = manifest.current_snapshot_id else {
285	        return Ok(None);
286	    };
287	    let path = snapshot_path(root, &sid);
288	    if !path.exists() {
289	        return Ok(None);
290	    }
291	    let bytes = fs::read(&path).map_err(|e| ForgeError::io("read snapshot", e))?;
292	    let snap: SelfModelSnapshot = serde_json::from_slice(&bytes).map_err(|e| {
293	        ForgeError::SelfModel(format!("self_model_error: bad snapshot record: {e}"))
294	    })?;
295	    Ok(Some(snap))
296	}
297	
298	/// Mark the current snapshot stale (e.g. after an extension mutation) without
299	/// mutating any immutable snapshot file. Records the reason in the manifest.
300	pub fn mark_current_stale(root: &Path, reason: &str) -> Result<(), ForgeError> {
301	    let Some(mut manifest) = read_manifest(root)? else {
302	        return Err(ForgeError::SelfModel(
303	            "self_model_error: cannot mark stale before init".into(),
304	        ));
305	    };
306	    manifest.stale = true;
307	    manifest.stale_reason = Some(reason.to_string());
308	    write_manifest(root, &manifest)?;
309	    Ok(())
310	}
311	
312	/// Whether the current snapshot is marked stale.
313	pub fn is_stale(root: &Path) -> Result<bool, ForgeError> {
314	    Ok(read_manifest(root)?.map(|m| m.stale).unwrap_or(false))
315	}
316	
317	/// Verify bundled models, validate the composed model, verify the current
318	/// snapshot's hash, and verify each persisted projection's rebuild_hash.
319	pub fn validate(root: &Path) -> Result<(), ForgeError> {
320	    let models = bundled();
321	    verify_bundled(&models)?;
322	    let _composed = load_composed(&models)?;
323	    if let Some(snap) = current_snapshot(root)? {
324	        verify_snapshot(&snap)?;
325	        if snap.freshness == SnapshotFreshness::Stale {
326	            // Stale is allowed but disclosed; not a validation failure.
327	        }
328	    }
329	    // Verify persisted projections.
330	    let pdir = projections_dir(root);
331	    if pdir.exists() {
332	        for entry in fs::read_dir(&pdir).map_err(|e| ForgeError::io("read projections dir", e))? {
333	            let entry = entry.map_err(|e| ForgeError::io("projection dir entry", e))?;
334	            let record_path = entry.path().join("projection-record.json");
335	            if record_path.exists() {
336	                let bytes = fs::read(&record_path)
337	                    .map_err(|e| ForgeError::io("read projection record", e))?;
338	                let record: sea_forge_core::types::ProjectionRecord =
339	                    serde_json::from_slice(&bytes).map_err(|e| {
340	                        ForgeError::SelfModel(format!(
341	                            "self_model_error: bad projection record: {e}"
342	                        ))
343	                    })?;
344	                verify_projection(&record)?;
345	            }
346	        }
347	    }
348	    Ok(())
349	}
