1	//! Self-model projections through the ProjectionRecord ABI (spec-adlc-thoth
2	//! §3.1, §10.1, slice 1.5). Produces KG/CALM/JSON(self_model_snapshot)
3	//! ProjectionRecords that are deterministic, rebuildable, and carry full
4	//! provenance. Two rebuilds from the same sources are byte-identical modulo
5	//! `created_at`.
6	
7	use crate::{canonical_sha256, ComposedModel, SelfModelSnapshot};
8	use sea_forge_core::errors::ForgeError;
9	use sea_forge_core::types::{
10	    ProjectionKind, ProjectionRecord, ProjectionStatus, ProjectionValidation, StageFile,
11	};
12	use sha2::{Digest, Sha256};
13	use std::collections::BTreeMap;
14	
15	const ADAPTER_REF: &str = "sea-forge-self-model";
16	
17	/// One self-model projection: its ProjectionRecord plus the materialized output
18	/// bytes keyed by the same full path used in `record.output_refs`.
19	#[derive(Clone, Debug)]
20	pub struct SelfModelProjection {
21	    pub record: ProjectionRecord,
22	    pub outputs: BTreeMap<String, String>,
23	}
24	
25	fn sha256_hex(bytes: &[u8]) -> String {
26	    format!("{:x}", Sha256::digest(bytes))
27	}
28	
29	/// Deterministic projection id from kind + snapshot hash prefix, so rebuilds of
30	/// the same snapshot produce byte-identical records (modulo created_at).
31	fn deterministic_projection_id(kind_label: &str, snapshot_hash: &str) -> String {
32	    let digest = snapshot_hash
33	        .strip_prefix("sha256:")
34	        .unwrap_or(snapshot_hash);
35	    let prefix = digest.len().min(16);
36	    format!("proj_{kind_label}_{}", &digest[..prefix])
37	}
38	
39	fn build(
40	    kind_label: &str,
41	    kind: ProjectionKind,
42	    raw_outputs: BTreeMap<String, String>,
43	    source_refs: Vec<String>,
44	    input_hash: &str,
45	    snapshot: &SelfModelSnapshot,
46	    created_at: &str,
47	) -> Result<SelfModelProjection, ForgeError> {
48	    // Re-key outputs under self-model/<kind_label>/ and build output_refs.
49	    let mut outputs: BTreeMap<String, String> = BTreeMap::new();
50	    let mut output_refs: Vec<StageFile> = Vec::with_capacity(raw_outputs.len());
51	    for (path, content) in raw_outputs {
52	        let full = format!("self-model/{kind_label}/{path}");
53	        let hash = format!("sha256:{}", sha256_hex(content.as_bytes()));
54	        output_refs.push(StageFile {
55	            path: full.clone(),
56	            sha256: hash,
57	            generated: true,
58	            ..Default::default()
59	        });
60	        outputs.insert(full, content);
61	    }
62	    output_refs.sort_by(|a, b| a.path.cmp(&b.path));
63	
64	    let rebuild_input = serde_json::json!({
65	        "adapter_ref": ADAPTER_REF,
66	        "source_refs": source_refs,
67	        "input_hash": input_hash,
68	        "output_refs": output_refs,
69	    });
70	    let rebuild_hash = canonical_sha256(&rebuild_input)?;
71	
72	    let record = ProjectionRecord {
73	        projection_id: deterministic_projection_id(kind_label, &snapshot.snapshot_hash),
74	        projection_kind: kind,
75	        adapter_ref: ADAPTER_REF.into(),
76	        case_id: "self-model".into(),
77	        run_id: snapshot.snapshot_id.clone(),
78	        domain_model_ref: None,
79	        source_refs,
80	        input_hash: input_hash.into(),
81	        output_refs,
82	        quarantine_refs: vec![],
83	        validation: ProjectionValidation {
84	            status: ProjectionStatus::Accepted,
85	            validator_ref: "sea-forge-self-model".into(),
86	            basis: vec!["deterministic_rebuild".into()],
87	        },
88	        authority_refs: vec![],
89	        evidence_refs: vec![],
90	        settlement_ref: None,
91	        created_at: created_at.into(),
92	        rebuild_hash,
93	    };
94	    Ok(SelfModelProjection { record, outputs })
95	}
96	
97	/// Build the three self-model projections (KG, CALM, self_model_snapshot).
98	/// Pure: no filesystem writes. Deterministic for fixed sources + created_at.
99	pub fn project_self(
100	    composed: &ComposedModel,
101	    snapshot: &SelfModelSnapshot,
102	    created_at: &str,
103	) -> Result<Vec<SelfModelProjection>, ForgeError> {
104	    use sea_forge_domainforge::project;
105	    let source_refs: Vec<String> = composed
106	        .system_model_ref()
107	        .source_refs
108	        .iter()
109	        .map(|s| s.uri.clone())
110	        .collect();
111	    let model_input_hash = composed.system_model_ref().semantic_model_sha256.clone();
112	
113	    let kg_outputs = project(&composed.system, &ProjectionKind::Kg)?;
114	    let calm_outputs = project(&composed.system, &ProjectionKind::Calm)?;
115	
116	    let snap_value = serde_json::to_value(snapshot)?;
117	    let snap_bytes = serde_json::to_vec_pretty(&snap_value)?;
118	    let snap_str = String::from_utf8(snap_bytes)
119	        .map_err(|e| sea_forge_core::ForgeError::Serialization(format!("snapshot utf-8: {e}")))?;
120	    let mut snap_outputs = BTreeMap::new();
121	    snap_outputs.insert("snapshot.json".into(), snap_str);
122	
123	    Ok(vec![
124	        build(
125	            "kg",
126	            ProjectionKind::Kg,
127	            kg_outputs,
128	            source_refs.clone(),
129	            &model_input_hash,
130	            snapshot,
131	            created_at,
132	        )?,
133	        build(
134	            "calm",
135	            ProjectionKind::Calm,
136	            calm_outputs,
137	            source_refs.clone(),
138	            &model_input_hash,
139	            snapshot,
140	            created_at,
141	        )?,
142	        build(
143	            "self_model_snapshot",
144	            ProjectionKind::SelfModelSnapshot,
145	            snap_outputs,
146	            source_refs,
147	            &snapshot.snapshot_hash,
148	            snapshot,
149	            created_at,
150	        )?,
151	    ])
152	}
153	
154	/// Recompute the rebuild_hash of a projection record from its stored fields and
155	/// confirm it matches. Drift ⇒ `self_model_error` (used to reject a pre-generated
156	/// projection whose output hash no longer matches its bytes).
157	pub fn verify_projection(record: &ProjectionRecord) -> Result<(), ForgeError> {
158	    let rebuild_input = serde_json::json!({
159	        "adapter_ref": record.adapter_ref,
160	        "source_refs": record.source_refs,
161	        "input_hash": record.input_hash,
162	        "output_refs": record.output_refs,
163	    });
164	    let expected = canonical_sha256(&rebuild_input)?;
165	    if expected != record.rebuild_hash {
166	        return Err(sea_forge_core::ForgeError::SelfModel(format!(
167	            "self_model_error: projection rebuild_hash mismatch for {}: declared={} computed={expected}",
168	            record.projection_id, record.rebuild_hash
169	        )));
170	    }
171	    Ok(())
172	}
