1	#![forbid(unsafe_code)]
2	
3	use chrono::Utc;
4	use sea_forge_authority::{AuthorityEvaluation, AuthorityPolicyBundle, PolicyAuthorityEngine};
5	use sea_forge_core::{errors::ForgeError, ids, types::*, RECORD_VERSION};
6	use sea_forge_ledger::LedgerStream;
7	use sea_forge_planner::case_engine::{next_case_actions, replay_case, CaseAction};
8	use serde::Serialize;
9	use serde_json::json;
10	use std::collections::BTreeMap;
11	use std::fs::{self, OpenOptions};
12	use std::io::Write;
13	use std::path::{Path, PathBuf};
14	
15	/// Synchronous case lifecycle operations shared by the CLI and server.
16	pub struct CaseRunner;
17	
18	impl CaseRunner {
19	    pub fn initialize_case(case_dir: &Path) -> Result<(PathBuf, PathBuf), ForgeError> {
20	        let runs_dir = case_dir.join("runs");
21	        fs::create_dir_all(&runs_dir).map_err(|error| ForgeError::io("create case runs", error))?;
22	        Ok((runs_dir, case_dir.join("case-events.jsonl")))
23	    }
24	
25	    pub fn next_ready_actions(items: &[PlanItem], events: &[TraceEvent]) -> Vec<CaseAction> {
26	        next_case_actions(items, events)
27	    }
28	
29	    pub fn append_event(
30	        path: &Path,
31	        stream: &LedgerStream,
32	        events: &mut Vec<TraceEvent>,
33	        kind: TraceKind,
34	        item_id: Option<&str>,
35	        mut payload: serde_json::Value,
36	    ) -> Result<(), ForgeError> {
37	        // Additive persisted ordinals (spec §17.2 T13.2): each dispatch/
38	        // activation and settlement gets a 1-based monotonic ordinal derived
39	        // from prior persisted events. Additive only — old readers ignore it.
40	        // ponytail: O(n) scan per append; switch to a runner-held counter if
41	        // a case ever accumulates thousands of dispatch/settlement events.
42	        match kind {
43	            TraceKind::ItemActivated => {
44	                let next = Self::next_ordinal(events, TraceKind::ItemActivated, "dispatch_ordinal");
45	                payload["dispatch_ordinal"] = serde_json::json!(next);
46	            }
47	            TraceKind::SettlementRecorded => {
48	                let next =
49	                    Self::next_ordinal(events, TraceKind::SettlementRecorded, "settlement_ordinal");
50	                payload["settlement_ordinal"] = serde_json::json!(next);
51	            }
52	            _ => {}
53	        }
54	        Self::commit_event(
55	            path,
56	            stream,
57	            events,
58	            TraceEvent {
59	                version: RECORD_VERSION.into(),
60	                event_id: ids::seq_id("cev", 6, events.len() + 1),
61	                run_id: "case".into(),
62	                plan_item_id: item_id.map(str::to_owned),
63	                kind,
64	                actor_id: "case_engine".into(),
65	                timestamp: Utc::now().to_rfc3339(),
66	                payload,
67	                cell_id: None,
68	            },
69	        )
70	    }
71	
72	    fn next_ordinal(events: &[TraceEvent], kind: TraceKind, key: &str) -> u64 {
73	        events
74	            .iter()
75	            .filter(|event| event.kind == kind)
76	            .filter_map(|event| event.payload.get(key).and_then(|value| value.as_u64()))
77	            .max()
78	            .unwrap_or(0)
79	            + 1
80	    }
81	
82	    pub fn commit_event(
83	        path: &Path,
84	        stream: &LedgerStream,
85	        events: &mut Vec<TraceEvent>,
86	        event: TraceEvent,
87	    ) -> Result<(), ForgeError> {
88	        stream.commit_typed("case_event", vec![], &event, vec![])?;
89	        let mut file = OpenOptions::new()
90	            .create(true)
91	            .append(true)
92	            .open(path)
93	            .map_err(|error| ForgeError::io("open case events", error))?;
94	        serde_json::to_writer(&mut file, &event)?;
95	        file.write_all(b"\n")
96	            .and_then(|_| file.flush())
97	            .map_err(|error| ForgeError::io("append case event", error))?;
98	        events.push(event);
99	        Ok(())
100	    }
101	
102	    pub fn run_sandboxed_episode<T>(
103	        execute: impl FnOnce() -> Result<T, ForgeError>,
104	    ) -> Result<T, ForgeError> {
105	        execute()
106	    }
107	
108	    #[allow(clippy::too_many_arguments)]
109	    pub fn apply_episode_completion(
110	        case: &mut Case,
111	        run_id: &str,
112	        item_id: &str,
113	        instance: u32,
114	        settlement: &SettlementEvent,
115	        case_events: &Path,
116	        stream: &LedgerStream,
117	        events: &mut Vec<TraceEvent>,
118	    ) -> Result<bool, ForgeError> {
119	        if !case.run_ids.iter().any(|existing| existing == run_id) {
120	            case.run_ids.push(run_id.into());
121	        }
122	        let accepted = settlement.status == SettlementStatus::Accepted;
123	        Self::append_event(
124	            case_events,
125	            stream,
126	            events,
127	            if accepted {
128	                TraceKind::ItemCompleted
129	            } else {
130	                TraceKind::ItemFailed
131	            },
132	            Some(item_id),
133	            json!({"instance": instance, "settlement": settlement.status}),
134	        )?;
135	        if accepted {
136	            Self::append_event(
137	                case_events,
138	                stream,
139	                events,
140	                TraceKind::MilestoneAchieved,
141	                Some(item_id),
142	                json!({"instance": instance}),
143	            )?;
144	        }
145	        Ok(accepted)
146	    }
147	}
148	
149	/// Outcome of driving a stage `CasePlan` to completion or a blocking point
150	/// (spec-audit-remediation Task 10A).
151	pub struct StageCaseOutcome {
152	    pub case: Case,
153	    pub stages: Vec<SpecPipelineStage>,
154	    pub events: Vec<TraceEvent>,
155	    /// `"completed"`, `"terminated"`, or `"active"` (blocked/no ready action).
156	    pub state: &'static str,
157	}
158	
159	/// Run a single stage episode: validate Task 9's prerequisite chain, deny
160	/// generated-zone edits before authority (§10.7, `generated_zone_direct_edit`),
161	/// then evaluate authority, execute under the granted sandbox, and settle —
162	/// mirroring the ordinary sandboxed-task episode pattern used elsewhere in
163	/// the workspace (no second authority/execution path for spec-pipeline
164	/// stages). Updates `stages[stage_index].status` in place and quarantines it
165	/// (via `sea_forge_spec_pipeline::quarantine_stage`) on any denial.
166	#[allow(clippy::too_many_arguments)]
167	fn run_stage_episode(
168	    stages: &mut [SpecPipelineStage],
169	    stage_index: usize,
170	    item: &PlanItem,
171	    policy_path: &Path,
172	    entity: &str,
173	    case_id: &str,
174	    run_id: &str,
175	    root: &Path,
176	    stream: &LedgerStream,
177	) -> Result<SettlementEvent, ForgeError> {
178	    if let Err(error) = sea_forge_spec_pipeline::validate_stage_prerequisites(stages, stage_index) {
179	        let reason = error.to_string();
180	        sea_forge_spec_pipeline::quarantine_stage(&mut stages[stage_index], &reason)?;
181	        return Ok(SettlementEvent {
182	            version: RECORD_VERSION.into(),
183	            settlement_id: ids::random_id("set")?,
184	            run_id: run_id.into(),
185	            status: SettlementStatus::Rejected,
186	            basis: vec!["prerequisite_invalid".into()],
187	            review_required: false,
188	            settled_at: Utc::now().to_rfc3339(),
189	            criteria_ref: item.settlement_criteria_ref.clone(),
190	        });
191	    }
192	
193	    // Generated-zone outputs (src/gen, AST, IR, manifests, generated semantic
194	    // fixtures) MUST be read-only to operators (§10.7). Only the pipeline's
195	    // own generator-kind stages may legitimately produce them; any other
196	    // stage kind declaring a generated-zone output is a denied
197	    // `run_spec_pipeline` operation, basis `generated_zone_direct_edit`,
198	    // rejected before authority is ever consulted.
199	    const GENERATOR_KINDS: &[StageKind] = &[
200	        StageKind::Ast,
201	        StageKind::Ir,
202	        StageKind::Manifest,
203	        StageKind::GeneratedContract,
204	        StageKind::SemanticFixture,
205	    ];
206	    if !GENERATOR_KINDS.contains(&stages[stage_index].kind) {
207	        let direct_edit = stages[stage_index]
208	            .outputs
209	            .iter()
210	            .any(|output| sea_forge_spec_pipeline::is_generated_zone(&output.path));
211	        if direct_edit {
212	            sea_forge_spec_pipeline::quarantine_stage(
213	                &mut stages[stage_index],
214	                "generated_zone_direct_edit",
215	            )?;
216	            return Ok(SettlementEvent {
217	                version: RECORD_VERSION.into(),
218	                settlement_id: ids::random_id("set")?,
219	                run_id: run_id.into(),
220	                status: SettlementStatus::Rejected,
221	                basis: vec!["generated_zone_direct_edit".into()],
222	                review_required: false,
223	                settled_at: Utc::now().to_rfc3339(),
224	                criteria_ref: item.settlement_criteria_ref.clone(),
225	            });
226	        }
227	    }
228	
229	    let operation = item
230	        .operations
231	        .first()
232	        .ok_or_else(|| ForgeError::Input("stage episode missing operation".into()))?
233	        .clone();
234	    let workspace = root
235	        .join("cases")
236	        .join(case_id)
237	        .join("runs")
238	        .join(run_id)
239	        .join("workspace");
240	    let artifacts = workspace.parent().unwrap().join("artifacts");
241	    fs::create_dir_all(&workspace).map_err(|e| ForgeError::io("create workspace", e))?;
242	    fs::create_dir_all(&artifacts).map_err(|e| ForgeError::io("create artifacts", e))?;
243	
244	    let bundle = AuthorityPolicyBundle::load(policy_path)?;
245	    let engine = PolicyAuthorityEngine::new(bundle.clone())?;
246	    let actor = Actor {
247	        actor_id: entity.into(),
248	        role: ActorRole::Operator,
249	    };
250	    let action = AuthorityAction::from(&operation);
251	    let decision = engine.evaluate(AuthorityEvaluation {
252	        actor: &actor,
253	        binding: bundle.resolve_identity(entity, ActorRole::Operator),
254	        run_id,
255	        case_id,
256	        plan_item_id: &item.plan_item_id,
257	        sequence: 1,
258	        action: &action,
259	        workspace_root: &workspace,
260	        evidence_refs: vec![],
261	        artifacts_root: Some(&artifacts),
262	        timeout_secs: Some(600),
263	        env_keys: ["PATH", "HOME"].into_iter().map(str::to_owned).collect(),
264	        domainforge_candidate: None,
265	        environment: None,
266	    })?;
267	    let decision_ref = stream.commit_typed(
268	        "authority_decision",
269	        vec![run_id.into(), item.plan_item_id.clone()],
270	        &decision,
271	        vec![],
272	    )?;
273	    let execution = if decision.verdict == Verdict::Allow {
274	        let grant = engine.grant(&decision, &decision_ref, &action, None)?;
275	        sea_forge_runtime::execute(
276	            grant,
277	            &ExecutionRequest {
278	                plan_item_id: item.plan_item_id.clone(),
279	                operation,
280	                timeout_secs: 600,
281	                env: BTreeMap::from([
282	                    (
283	                        String::from("PATH"),
284	                        std::env::var("PATH").unwrap_or_default(),
285	                    ),
286	                    (
287	                        String::from("HOME"),
288	                        std::env::var("HOME").unwrap_or_default(),
289	                    ),
290	                ]),
291	                compensating_controls: decision.compensating_controls.clone(),
292	            },
293	            run_id,
294	            &workspace,
295	            &artifacts,
296	        )?
297	    } else {
298	        ExecutionResult {
299	            status: ExecutionStatus::SpawnFailed,
300	            exit_code: None,
301	            stdout_path: String::new(),
302	            stderr_path: String::new(),
303	            started_at: Utc::now().to_rfc3339(),
304	            finished_at: Utc::now().to_rfc3339(),
305	        }
306	    };
307	    let accepted = decision.verdict == Verdict::Allow
308	        && execution.status == ExecutionStatus::Completed
309	        && execution.exit_code == Some(0);
310	    stages[stage_index].status = if accepted {
311	        StageStatus::Accepted
312	    } else {
313	        StageStatus::Rejected
314	    };
315	    if !accepted {
316	        sea_forge_spec_pipeline::quarantine_stage(
317	            &mut stages[stage_index],
318	            if decision.verdict == Verdict::Allow {
319	                "stage_execution_failed"
320	            } else {
321	                "authority_denied"
322	            },
323	        )?;
324	    }
325	    Ok(SettlementEvent {
326	        version: RECORD_VERSION.into(),
327	        settlement_id: ids::random_id("set")?,
328	        run_id: run_id.into(),
329	        status: if accepted {
330	            SettlementStatus::Accepted
331	        } else {
332	            SettlementStatus::Rejected
333	        },
334	        basis: vec![if accepted {
335	            "execution_completed".into()
336	        } else if decision.verdict == Verdict::Allow {
337	            // Authority allowed but the run did not accept (nonzero exit,
338	            // spawn failure, etc.) — mirror quarantine_stage's basis so the
339	            // settlement record distinguishes execution failure from denial.
340	            "stage_execution_failed".into()
341	        } else {
342	            "authority_denied".into()
343	        }],
344	        review_required: false,
345	        settled_at: Utc::now().to_rfc3339(),
346	        criteria_ref: item.settlement_criteria_ref.clone(),
347	    })
348	}
349	
350	/// Drive a stage `CasePlan` (from `sea_forge_planner::stage_case_plan`) to
351	/// completion as an ordinary governed case: every stage activation, quarantine,
352	/// and settlement is an existing case/authority/ledger record, not a separate
353	/// spec-pipeline scheduler (Task 10A). `stages` must be in the same order and
354	/// carry the same `stage_id`s as `plan.items[*].plan_item_id`.
355	pub fn run_stage_case(
356	    root: &Path,
357	    policy_path: &Path,
358	    entity: &str,
359	    plan: &CasePlan,
360	    mut stages: Vec<SpecPipelineStage>,
361	) -> Result<StageCaseOutcome, ForgeError> {
362	    let case_id = plan.case_id.clone();
363	    let case_dir = root.join("cases").join(&case_id);
364	    let (_runs_dir, case_events) = CaseRunner::initialize_case(&case_dir)?;
365	    let stream = LedgerStream::open(root, format!("case-{case_id}"), entity)?;
366	    stream.commit_typed("case_plan", vec![case_id.clone()], plan, vec![])?;
367	
368	    let mut case = Case {
369	        version: RECORD_VERSION.into(),
370	        case_id: case_id.clone(),
371	        intent: Intent {
372	            intent_id: plan.intent_id.clone(),
373	            summary: format!("Execute spec pipeline for case {case_id}"),
374	            actor_id: entity.into(),
375	            process_id: "spec_pipeline".into(),
376	            created_at: Utc::now().to_rfc3339(),
377	        },
378	        state: CaseState::Active,
379	        plan_ref: plan.plan_id.clone(),
380	        run_ids: vec![],
381	        stages: plan
382	            .items
383	            .iter()
384	            .map(|item| item.plan_item_id.clone())
385	            .collect(),
386	        close_reason: None,
387	        created_at: Utc::now().to_rfc3339(),
388	        closed_at: None,
389	    };
390	    write_json(&case_dir.join("case.json"), &case)?;
391	    write_json(&case_dir.join("plan.json"), plan)?;
392	
393	    let mut events = vec![];
394	    CaseRunner::append_event(
395	        &case_events,
396	        &stream,
397	        &mut events,
398	        TraceKind::CaseCreated,
399	        None,
