1	//! Self-model commands (spec-adlc-thoth §11.1): validate, rebuild, show.
2	//!
3	//! All three go through `sea_forge_self_model::store`. `rebuild [--probe]` is
4	//! the lifecycle entry: it ensures init, then rebuilds a snapshot. Probe
5	//! *execution* (authority-checked sandbox runs of environment-contract commands)
6	//! is the CLI/server's job; here it is a no-op stub until the probe runner is
7	//! wired (the store consumes evidenced probe results, never running commands).
8	
9	use sea_forge_core::errors::ForgeError;
10	use sea_forge_extension::{ExtensionRegistry, ExtensionStatus};
11	use sea_forge_self_model::{
12	    store,
13	    store::{read_cell_realization, RebuildInputs},
14	    ExtensionState,
15	};
16	use std::path::Path;
17	
18	fn now_iso() -> String {
19	    chrono::Utc::now().to_rfc3339()
20	}
21	
22	fn default_cell_id(root: &Path) -> Result<String, ForgeError> {
23	    // Reuse the cell id if a cell.json realization exists; else a stable local default.
24	    if let Some(cell) = read_cell_realization(root)? {
25	        return Ok(cell.cell_id);
26	    }
27	    Ok("cell_local".into())
28	}
29	
30	/// Real active-extension state from the installation's own extension registry
31	/// (`.sea-forge/extensions/registry.json`), replacing the caller-supplied
32	/// empty vec (Task 11 audit remediation). An absent registry is a fresh
33	/// installation with zero extensions, not an error.
34	fn active_extensions_from_registry(root: &Path) -> Result<Vec<ExtensionState>, ForgeError> {
35	    let registry = ExtensionRegistry::load(&root.join(".sea-forge"))?;
36	    Ok(registry
37	        .extensions
38	        .into_iter()
39	        .map(|entry| ExtensionState {
40	            descriptor_ref: format!("{}@{}", entry.extension_id, entry.version),
41	            status: match entry.status {
42	                ExtensionStatus::Active => "active",
43	                ExtensionStatus::Disabled => "disabled",
44	                ExtensionStatus::Quarantined => "quarantined",
45	                ExtensionStatus::Superseded => "superseded",
46	            }
47	            .to_string(),
48	        })
49	        .collect())
50	}
51	
52	/// Real sandbox classes this host can currently construct, replacing the
53	/// caller-supplied hardcoded `["local"]` (Task 11 audit remediation). `local`
54	/// is always available; other classes are probed by attempting construction.
55	fn real_sandbox_classes_available() -> Vec<String> {
56	    use sea_forge_sandbox::{select_sandbox, SandboxClass};
57	    [
58	        SandboxClass::Local,
59	        SandboxClass::Jail,
60	        SandboxClass::Microvm,
61	    ]
62	    .into_iter()
63	    .filter(|class| select_sandbox(*class).is_ok())
64	    .map(|class| class.to_string())
65	    .collect()
66	}
67	
68	/// Real, non-placeholder commitment over the demonstrated-capability surface
69	/// (`.sea-forge/capabilities.jsonl`), replacing the fixed
70	/// `sha256:capability-projection` CLI default literal (Task 11 audit
71	/// remediation). An absent or empty file hashes to a well-defined, still-real
72	/// "no capability data yet" digest rather than a fabricated placeholder.
73	fn real_capability_projection_sha256(root: &Path) -> Result<String, ForgeError> {
74	    let path = root.join(".sea-forge").join("capabilities.jsonl");
75	    let envelopes = if path.exists() {
76	        sea_forge_capability::load_envelopes(&path)?
77	    } else {
78	        vec![]
79	    };
80	    sea_forge_self_model::canonical_sha256(&envelopes)
81	}
82	
83	/// `sea-forge self-model validate` — verify bundled models, validate the
84	/// composed model, verify the current snapshot + persisted projections. Exit 0/1.
85	pub fn validate(root: &Path) -> Result<u8, ForgeError> {
86	    store::validate(root)?;
87	    println!("self-model: valid (bundled models verified; snapshot + projections verified)");
88	    Ok(0)
89	}
90	
91	/// `sea-forge self-model rebuild [--probe]` — init-or-upgrade, then build a new
92	/// snapshot from the release realization + cell realization. `--probe` is
93	/// accepted but probe execution is deferred to the sandbox layer (no-op here).
94	/// Inputs come from verified installation state (extension registry, sandbox
95	/// availability, demonstrated-capability envelopes) rather than caller-supplied
96	/// placeholders (Task 11 audit remediation).
97	pub fn rebuild(root: &Path, _probe: bool, actor_id: &str) -> Result<u8, ForgeError> {
98	    let cell_id = default_cell_id(root)?;
99	    let active_extensions = active_extensions_from_registry(root)?;
100	    let capability_hash = real_capability_projection_sha256(root)?;
101	    let sandbox_classes_available = real_sandbox_classes_available();
102	    let created_at = now_iso();
103	    let inputs = RebuildInputs {
104	        cell_id: &cell_id,
105	        active_extensions,
106	        environments_present: vec![],
107	        probes: vec![],
108	        sandbox_classes_available,
109	        created_at: &created_at,
110	        capability_projection_sha256: &capability_hash,
111	        actor_id,
112	    };
113	    let snapshot = store::rebuild(root, &inputs)?;
114	    println!("snapshot_id={}", snapshot.snapshot_id);
115	    println!("release_id={}", snapshot.release_id);
116	    println!("snapshot_hash={}", snapshot.snapshot_hash);
117	    println!("freshness={:?}", snapshot.freshness);
118	    Ok(0)
119	}
120	
121	/// `sea-forge self-model show [--json]` — composed-view summary from the newest
122	/// snapshot; `--json` emits the full snapshot record.
123	pub fn show(root: &Path, json: bool) -> Result<u8, ForgeError> {
124	    let Some(snapshot) = store::current_snapshot(root)? else {
125	        if json {
126	            println!("null");
127	        } else {
128	            println!("(no self-model snapshot; run `sea-forge self-model rebuild`)");
129	        }
130	        return Ok(0);
131	    };
132	    if json {
133	        println!(
134	            "{}",
135	            serde_json::to_string_pretty(&snapshot)
136	                .map_err(|e| ForgeError::Serialization(e.to_string()))?
137	        );
138	        return Ok(0);
139	    }
140	    println!("snapshot_id={}", snapshot.snapshot_id);
141	    println!("release_id={}", snapshot.release_id);
142	    println!("snapshot_hash={}", snapshot.snapshot_hash);
143	    println!("freshness={:?}", snapshot.freshness);
144	    println!(
145	        "system_model_sha256={}",
146	        snapshot.system_model_ref.semantic_model_sha256
147	    );
148	    println!(
149	        "release_realization_sha256={}",
150	        snapshot.release_realization_sha256
151	    );
152	    println!(
153	        "cell_realization_sha256={}",
154	        snapshot.cell_realization_sha256
155	    );
156	    println!(
157	        "capability_projection_sha256={}",
158	        snapshot.capability_projection_sha256
