55	                    "plan_item_id": "A",
56	                    "name": "A",
57	                    "operations": [{"kind":"write_file","path":"a.txt","content_hint":"ok"}],
58	                    "entry_criteria": [], "exit_criteria": [],
59	                    "settlement_criteria": {"require_exit_zero":false,"required_artifacts":["a.txt"],"stdout_must_contain":null,"require_approval":false},
60	                    "item_kind":"sandboxed_task","sandbox_class":"local","parent_stage":null,
61	                    "markers":{"required":true,"repetition":false,"manual_activation":false},
