95	/// criteria via `derive_from_template`, and resolves the desired-outcome
96	/// origin ref against the real, bundled self-model seed hash — the exact
97	/// same hash `sea_forge_self_model` independently reports for that seed.
98	#[test]
99	fn t10_6_production_plan_with_odi_template_resolves_real_desired_outcome() {
100	    let parent = temp_root();
101	    let root = parent.join("state");
102	    let policy = write_policy(&parent);
103	    let plan = write_plan(&parent, "odi_adlc_case@0.1.0");
104	
105	    let (code, stdout, stderr) = run_plan(&root, &plan, &policy);
106	    assert_eq!(code, 0, "stdout: {stdout}\nstderr: {stderr}");
107	
108	    // The source-owned installer materialized the pinned built-in template.
109	    let installed = root.join("templates/odi_adlc_case@0.1.0.yaml");
110	    assert!(
111	        installed.exists(),
112	        "built-in template must be installed under <root>/templates/"
113	    );
114	
115	    // The committed settlement_criteria record carries a real desired-outcome
116	    // origin ref whose hash matches the actual bundled seed model hash.
117	    let models = sea_forge_self_model::bundled();
118	    let composed = sea_forge_self_model::load_composed(&models).unwrap();
119	    let expected_hash = composed.seed_model_ref().semantic_model_sha256.clone();
120	
121	    let case_dirs: Vec<_> = fs::read_dir(root.join("cases")).unwrap().collect();
122	    assert_eq!(case_dirs.len(), 1);
123	    let case_dir = case_dirs.into_iter().next().unwrap().unwrap().path();
124	    let entries_path = case_dir
125	        .file_name()
126	        .map(|name| {
127	            root.join("ledgers")
128	                .join(format!("case-{}", name.to_string_lossy()))
129	                .join("entries.jsonl")
130	        })
131	        .unwrap();
132	    let text = fs::read_to_string(&entries_path).unwrap();
133	    let mut found_desired_outcome = false;
134	    for line in text.lines().filter(|l| !l.trim().is_empty()) {
135	        let entry: serde_json::Value = serde_json::from_str(line).unwrap();
136	        if entry["record_kind"] != "settlement_criteria" {
137	            continue;
138	        }
139	        for origin in entry["payload"]["origin_refs"].as_array().unwrap() {
140	            if origin["kind"] == "desired_outcome" {
141	                found_desired_outcome = true;
142	                assert_eq!(origin["sha256"], expected_hash);
143	                assert_ne!(origin["sha256"], "sha256:placeholder");
144	                assert_eq!(origin["reference"], "Desired Outcome Criterion");
145	            }
146	        }
147	    }
148	    assert!(
149	        found_desired_outcome,
150	        "expected a desired_outcome origin ref in a committed settlement_criteria record"
151	    );
152	
153	    let _ = fs::remove_dir_all(&parent);
154	}
