82	fn run_plan_inner(
83	    options: PlanRunOptions,
84	    mut approval_extension: Option<PlanApprovalExtension>,
85	) -> Result<PlanRunOutcome, ForgeError> {
86	    // Proposal and policy validation precede state creation.
87	    let mut plan = load_plan(&options.plan)?;
88	    validate_proposal(&mut plan)?;
89	    let bundle = AuthorityPolicyBundle::load(&options.policy)?;
90	    let engine = PolicyAuthorityEngine::new(bundle.clone())?;
91	
92	    fs::create_dir_all(&options.root)
93	        .map_err(|error| ForgeError::io("create state root", error))?;
94	    let root = options
95	        .root
96	        .canonicalize()
97	        .map_err(|error| ForgeError::io("canonicalize state root", error))?;
98	    let case_id = ids::case_id()?;
99	    plan.case_id.clone_from(&case_id);
100	    let case_dir = root.join("cases").join(&case_id);
101	    let (runs_dir, case_events) = CaseRunner::initialize_case(&case_dir)?;
102	    let stream = LedgerStream::open(&root, format!("case-{case_id}"), &options.entity)?;
103	    stream.commit_typed("case_plan", vec![case_id.clone()], &plan, vec![])?;
104	
105	    let intent = Intent {
106	        intent_id: ids::random_id("int")?,
107	        summary: options
108	            .intent_summary
109	            .clone()
110	            .unwrap_or_else(|| format!("Execute plan {}", options.plan.display())),
111	        actor_id: options.entity.clone(),
112	        process_id: options.process.clone(),
113	        created_at: Utc::now().to_rfc3339(),
114	    };
115	    let actor = Actor {
116	        actor_id: options.entity.clone(),
117	        role: ActorRole::Operator,
118	    };
119	    let binding = bundle.resolve_identity(&actor.actor_id, actor.role.clone());
120	
121	    // Real desired-outcome resolver over Task 11's validated self-model seed
122	    // (audit remediation Task 12) — never the fail-closed NoModelResolver
123	    // wrapper for externally supplied plans.
124	    let (desired_outcome_resolver, seed_domain_model_ref, seed_model_sha256) =
125	        crate::pipeline::seed_desired_outcome_resolver()?;
126	
127	    // A submitted plan naming a known built-in template derives its criteria
128	    // from that template (desired-outcome provenance included) rather than
129	    // intent-only provenance; materializing it through the source-owned
130	    // installer (`store_builtin`) and loading the pinned, tamper-evident copy
131	    // (`load_pinned`) is the same path any other consumer of that template
132	    // would take (Task 12 audit remediation step 3).
133	    let built_in_template = match plan.template_ref.as_deref() {
134	        Some(reference) if sea_forge_planner::is_built_in_template_ref(reference) => {
135	            sea_forge_planner::store_builtin(&root, &seed_domain_model_ref, &seed_model_sha256)?;
136	            Some(sea_forge_planner::load_pinned(&root, reference)?)
137	        }
138	        _ => None,
139	    };
140	
141	    // Derive and commit settlement criteria records for every settling item.
142	    let mut criteria_map: BTreeMap<String, SettlementCriteriaRecord> = BTreeMap::new();
143	    let declared_at = Utc::now().to_rfc3339();
144	    for item in &mut plan.items {
145	        let mut record = if let Some(template) = &built_in_template {
146	            sea_forge_planner::derive_from_template(
147	                template,
148	                item,
