4	/// Separation-of-duties check (§10.3, §15, T11.7).
5	/// Thoth cannot settle a claim it authored or promote its own capability.
6	/// The check compares immutable `authored_by` provenance against the
7	/// declarer/promoter identity. Re-labeling, copying, or replaying a claim
8	/// cannot remove the binding — `authored_by` is part of the canonical hash.
9	pub fn check_sod(authored_by: Option<&str>, declarer_id: &str) -> Result<(), ForgeError> {
10	    if let Some(author) = authored_by {
11	        if author == declarer_id {
12	            return Err(ForgeError::Plan {
13	                class: "sod_violation",
14	                message: format!(
15	                    "actor '{declarer_id}' cannot settle or promote a claim it authored ('{author}')"
16	                ),
17	            });
18	        }
19	    }
20	    Ok(())
21	}
