59	/// Disclosure policy: which actor roles may see which claim classes.
60	/// Wraps the authority surface's permit check (§8.2).
61	pub trait DisclosurePolicy {
62	    /// Returns true if `actor_role` is permitted to disclose `claim_class`.
63	    /// Absent surface ⇒ deny (§8.2, T11.8).
64	    fn permits(&self, actor_role: &str, claim_class: &ClaimClass) -> bool;
65	    /// Whether this policy requires a fresh (non-stale) snapshot.
66	    fn requires_fresh(&self) -> bool {
67	        false
68	    }
69	}
70	
71	/// The fixed authority notice.
72	const AUTHORITY_NOTICE: &str = "This answer confers no execution authority.";
73	
74	/// Resolve a question into an answer through the disclosure pipeline (§16.2).
75	///
76	/// Steps: classify → check policy → deny or plan → bounded query → claim
77	/// derivation → answer assembly. Deterministic over (question, snapshot,
78	/// policy).
79	pub fn answer_question(
80	    question: &ThothQuestion,
81	    snapshot: &dyn SnapshotView,
82	    policy: &dyn DisclosurePolicy,
83	    answer_id: &str,
84	    answered_at: &str,
85	) -> ThothAnswer {
86	    let candidates = candidate_classes(&question.kind);
87	    // Classify which candidate classes are permitted for this actor.
88	    let permitted: Vec<ClaimClass> = candidates
89	        .iter()
90	        .filter(|c| policy.permits(&question.actor_id, c))
91	        .cloned()
92	        .collect();
93	    let omitted: Vec<ClaimClass> = candidates
94	        .iter()
95	        .filter(|c| !permitted.contains(c))
96	        .cloned()
97	        .collect();
98	
99	    // If nothing is permitted, deny. Denial names classes only (§10.3).
100	    if permitted.is_empty() && !candidates.is_empty() {
101	        return ThothAnswer::denied(
102	            &question.question_id,
103	            answer_id,
104	            candidates.clone(),
105	            snapshot.snapshot_ref(),
106	            answered_at,
107	        );
108	    }
109	
110	    // ask_why_denied is handled separately — reads recorded denial, no query.
111	    if question.kind == QuestionKind::AskWhyDenied {
112	        return ThothAnswer {
113	            answer_id: answer_id.into(),
114	            question_id: question.question_id.clone(),
115	            disposition: Disposition::Denied,
116	            claims: vec![],
117	            omitted_claim_classes: vec![],
118	            snapshot_ref: snapshot.snapshot_ref().to_owned(),
119	            freshness: freshness_of(snapshot, policy),
120	            assurance: "local_tamper_evident".into(),
121	            limitations: vec![],
122	            authority_notice: AUTHORITY_NOTICE.into(),
123	            answered_at: answered_at.into(),
124	        };
125	    }
126	
127	    // Bounded query: derive claims only from permitted classes.
128	    let claims = derive_claims(&question.kind, &question.subject, snapshot, &permitted);
129	    let freshness = freshness_of(snapshot, policy);
130	    let disposition = if omitted.is_empty() {
131	        Disposition::Answered
132	    } else {
133	        Disposition::Partial
134	    };
135	
136	    ThothAnswer {
137	        answer_id: answer_id.into(),
138	        question_id: question.question_id.clone(),
139	        disposition,
140	        claims,
141	        omitted_claim_classes: omitted,
142	        snapshot_ref: snapshot.snapshot_ref().to_owned(),
143	        freshness,
144	        assurance: "local_tamper_evident".into(),
145	        limitations: vec![],
146	        authority_notice: AUTHORITY_NOTICE.into(),
147	        answered_at: answered_at.into(),
148	    }
149	}
150	
151	fn freshness_of(snapshot: &dyn SnapshotView, policy: &dyn DisclosurePolicy) -> Freshness {
152	    if snapshot.is_stale() && policy.requires_fresh() {
153	        // ponytail: a policy that requires fresh + stale snapshot should refuse.
154	        // For now, we disclose stale (T11.9 tests this).
155	        Freshness::Stale
156	    } else if snapshot.is_stale() {
157	        Freshness::Stale
158	    } else {
159	        Freshness::Current
160	    }
161	}
