         let authority_committed = stream.commit_typed("authority_decision", vec![snapshot.snapshot_id.clone()], &decision, vec![evidence_committed.entry_ulid().to_string()])?;
         let settlement = SettlementEvent { version: KERNEL_VERSION.into(), settlement_id: ids::random_id("set")?, run_id: snapshot.snapshot_id.clone(), status: SettlementStatus::Accepted, basis: vec!["self_model_snapshot_verified".into()], review_required: false, settled_at: inputs.created_at.to_string(), criteria_ref: None };
         let settlement_committed = stream.commit_typed("settlement_event", vec![snapshot.snapshot_id.clone()], &settlement, vec![authority_committed.entry_ulid().to_string()])?;
         let authority_refs = vec![authority_committed.entry_ulid().to_string()];
         let evidence_refs = vec![evidence_committed.entry_ulid().to_string()];
         let settlement_ref = Some(settlement_committed.entry_ulid().to_string());
