         let release = release_realization();
         let release_committed = stream.commit_typed_once("self_model_release_realization", release.release_id.clone(), vec![], &release, vec![])?;
         stream.materialize_view(&release_committed, &realization_dir(root).join("release.json"), &serde_json::to_vec_pretty(&release)?)?;
         let cell_committed = stream.commit_typed("self_model_cell_realization", vec![snapshot.snapshot_id.clone()], &cell, authority_refs.clone())?;
         stream.materialize_view(&cell_committed, &realization_dir(root).join("cell.json"), &serde_json::to_vec_pretty(&cell)?)?;
         let snapshot_committed = stream.commit_typed_new("self_model_snapshot", snapshot.snapshot_id.clone(), vec![snapshot.snapshot_id.clone()], &snapshot, authority_refs)?;
         stream.materialize_view(&snapshot_committed, &snapshot_path(root, &snapshot.snapshot_id), &serde_json::to_vec_pretty(&snapshot)?)?;
