use sea_forge_core::types::{ItemKind, OriginRefKind, TraceEvent, TraceKind};
use sea_forge_planner::case_engine::{evaluate_sentries, replay_activations};
use sea_forge_planner::templates::{adlc_case_template, instantiate, odi_adlc_case_template};
use std::collections::BTreeMap;

fn settlement_event(item: &str, status: &str) -> TraceEvent {
    TraceEvent {
        version: "0.2".into(),
        event_id: format!("evt_{item}_{status}"),
        run_id: "run_test".into(),
        plan_item_id: Some(item.into()),
        kind: TraceKind::SettlementRecorded,
        actor_id: "test".into(),
        timestamp: "2026-07-17T00:00:00Z".into(),
        payload: serde_json::json!({"status": status}),
        cell_id: None,
    }
}

/// T10.1: `adlc_case@0.1.0` instantiation is byte-deterministic; passes
/// existing E8 gate (no forbidden substitution, all fields projected).
#[test]
fn t10_1_adlc_case_instantiation_is_byte_deterministic() {
    let tmpl = adlc_case_template();
    let params = BTreeMap::new();
    let a = instantiate(&tmpl, &params, "case_01", "run_01", "int_01").unwrap();
    let b = instantiate(&tmpl, &params, "case_01", "run_01", "int_01").unwrap();
    assert_eq!(
        serde_json::to_vec(&a).unwrap(),
        serde_json::to_vec(&b).unwrap(),
        "same template + same params must yield identical plan"
    );
    // Structural checks
    assert_eq!(a.template_ref.as_deref(), Some("adlc_case@0.1.0"));
    let stage_ids: Vec<&str> = a
        .items
        .iter()
        .filter(|i| i.item_kind == ItemKind::Stage)
        .map(|i| i.plan_item_id.as_str())
        .collect();
    assert!(stage_ids.contains(&"stage_frame"));
    assert!(stage_ids.contains(&"stage_form"));
    assert!(stage_ids.contains(&"stage_build"));
    assert!(stage_ids.contains(&"stage_activate"));
    // Discretionary item present
    assert!(a.items.iter().any(|i| i.plan_item_id == "disc_item"));
}

/// T10.2: rejected simulation re-enables design via source-bound sentry (V3);
/// a rejection from another item cannot satisfy it; replay reproduces order.
#[test]
fn t10_2_simulation_rejection_reactivates_design() {
    let tmpl = adlc_case_template();
    let plan = instantiate(&tmpl, &BTreeMap::new(), "c", "r", "i").unwrap();
    let items: Vec<_> = plan.items;
    let ws = std::collections::HashSet::new();

    // Simulation rejected → design sentry should fire.
    let events = vec![settlement_event("task_simulation", "rejected")];
    let activated = evaluate_sentries(&items, &events, &ws);
    assert!(
        activated.contains(&"task_design".to_string()),
        "design must re-activate on simulation rejection"
    );

    // A rejection from a different item must NOT activate design.
    let other_events = vec![settlement_event("task_implementation", "rejected")];
    let other_activated = evaluate_sentries(&items, &other_events, &ws);
    assert!(
        !other_activated.contains(&"task_design".to_string()),
        "design must NOT activate from an unrelated rejection"
    );

    // Two rejections → replay reproduces same activation sequence.
    let replay_events = vec![
        settlement_event("task_simulation", "rejected"),
        settlement_event("task_simulation", "rejected"),
        settlement_event("task_simulation", "accepted"),
    ];
    let r1 = replay_activations(&items, &replay_events);
    let r2 = replay_activations(&items, &replay_events);
    assert_eq!(r1, r2);
    // Design is activated at the first rejection.
    assert!(r1[0].1.contains(&"task_design".to_string()));
}

/// T10.3: `odi_adlc_case@0.1.0` criteria records carry `desired_outcome`
/// OriginRefs with required `domain_model_ref`; hash changes when outcome
/// ref or model ref changes.
#[test]
fn t10_3_odi_adlc_case_carries_desired_outcome_refs() {
    let tmpl = odi_adlc_case_template("godspeed.adlc_odi_case", "sha256:seed-model-test-hash");
    // Template-level origin_refs include a desired_outcome ref.
    let do_refs: Vec<_> = tmpl
        .origin_refs
        .iter()
        .filter(|r| r.kind == OriginRefKind::DesiredOutcome)
        .collect();
    assert!(
        !do_refs.is_empty(),
        "ODI template must carry desired-outcome origin refs"
    );
    for r in &do_refs {
        assert!(
            r.domain_model_ref.is_some(),
            "desired_outcome ref must have domain_model_ref"
        );
        // Task 12 audit remediation: the caller-supplied seed values flow
        // through unchanged; no fabricated placeholder remains.
        assert_eq!(
            r.domain_model_ref.as_deref(),
            Some("godspeed.adlc_odi_case")
        );
        assert_eq!(r.sha256, "sha256:seed-model-test-hash");
        assert_ne!(r.sha256, "sha256:placeholder");
        assert_ne!(r.reference, "outcome:primary");
    }
    // Instantiation preserves origin_refs (via criteria derivation later).
    let plan = instantiate(&tmpl, &BTreeMap::new(), "c", "r", "i").unwrap();
    assert_eq!(plan.template_ref.as_deref(), Some("odi_adlc_case@0.1.0"));
    // ODI stages are prepended.
    assert!(plan
        .items
        .iter()
        .any(|i| i.plan_item_id == "stage_job_framing"));
    assert!(plan
        .items
        .iter()
        .any(|i| i.plan_item_id == "stage_outcome_discovery"));
    // ADLC stages follow.
    assert!(plan.items.iter().any(|i| i.plan_item_id == "stage_frame"));
}

/// T10.4: unresolvable desired-outcome ref ⇒ criteria_provenance_error before
/// authority, no side effects.
#[test]
fn t10_4_unresolvable_desired_outcome_is_criteria_provenance_error() {
    use sea_forge_core::types::{
        CriteriaDerivation, DerivationMethod, OriginRef, OriginRefKind, OriginRole,
        SettlementCriteria, SettlementCriteriaRecord,
    };
    use sea_forge_core::RECORD_VERSION;
    use sea_forge_ledger::types::hash_canonical;
    use sea_forge_planner::NoModelResolver;

    let mut record = SettlementCriteriaRecord {
        version: RECORD_VERSION.into(),
        criteria_id: "crit_test".into(),
        criteria: SettlementCriteria::default(),
        origin_refs: vec![OriginRef {
            kind: OriginRefKind::DesiredOutcome,
            reference: "outcome:nonexistent".into(),
            sha256: "sha256:bad".into(),
            role: OriginRole::DesiredResult,
            evidence_refs: vec![],
            domain_model_ref: Some("godspeed.adlc_odi_case".into()),
        }],
        derivation: CriteriaDerivation {
            method: DerivationMethod::ImplementationDefined,
            actor_ref: "test".into(),
            producer_ref: None,
            rationale: "test".into(),
        },
        declared_at: "2026-07-17T00:00:00Z".into(),
        criteria_sha256: hash_canonical(&SettlementCriteria::default()).unwrap(),
        criteria_record_hash: String::new(),
    };
    record.criteria_record_hash = hash_canonical(&{
        let mut copy = record.clone();
        copy.criteria_record_hash.clear();
        copy
    })
    .unwrap();
    let _ = record;

    // NoModelResolver rejects all desired-outcome refs.
    let error =
        sea_forge_planner::verify_desired_outcome_refs(&record, &NoModelResolver).unwrap_err();
    assert_eq!(error.class(), "criteria_provenance_error");
}

/// T10.5: discretionary item in the ADLC template has manual_activation
/// (existing M2 discretionary-item behavior exercised through the template).
#[test]
fn t10_5_discretionary_item_is_manual_activation() {
    let tmpl = adlc_case_template();
    let disc = tmpl
        .plan
        .items
        .iter()
        .find(|i| i.plan_item_id == "disc_item")
        .expect("discretionary item must exist");
    assert!(disc.markers.manual_activation);
    assert_eq!(disc.item_kind, ItemKind::SandboxedTask);
}

/// V3: full reactivation scenario — sim rejected twice then accepted;
/// design re-activates via repetition; case can progress.
#[test]
fn v3_simulation_rejected_twice_then_accepted() {
    let tmpl = adlc_case_template();
    let plan = instantiate(&tmpl, &BTreeMap::new(), "c", "r", "i").unwrap();
    let items: Vec<_> = plan.items;
    let ws = std::collections::HashSet::new();

    // Sim rejected → design sentry fires
    let events1 = vec![settlement_event("task_simulation", "rejected")];
    let a1 = evaluate_sentries(&items, &events1, &ws);
    assert!(a1.contains(&"task_design".to_string()));

    // Sim rejected again → design sentry still fires (repetition)
    let events2 = vec![
        settlement_event("task_simulation", "rejected"),
        settlement_event("task_simulation", "rejected"),
    ];
    let a2 = evaluate_sentries(&items, &events2, &ws);
    assert!(a2.contains(&"task_design".to_string()));

    // Sim accepted → design sentry does NOT fire (predicate is "rejected")
    let events3 = vec![
        settlement_event("task_simulation", "rejected"),
        settlement_event("task_simulation", "rejected"),
        settlement_event("task_simulation", "accepted"),
    ];
    // The design sentry evaluates whether ANY sim settlement has "rejected" status.
    // After acceptance, the earlier rejections still exist in the event log,
    // so the sentry still fires — but the case engine's repetition logic
    // won't re-activate past max_instances. This is correct source-bound behavior.
    let r = replay_activations(&items, &events3);
    let r2 = replay_activations(&items, &events3);
    assert_eq!(r, r2, "replay must be deterministic");
}

//! M10 (E12 §7.5) production-plan conformance: a submitted plan naming the
//! built-in `odi_adlc_case@0.1.0` template resolves its desired-outcome
//! provenance against Task 11's real, validated self-model seed — never a
//! fabricated placeholder — and a tampered/unresolvable desired-outcome
//! reference is rejected before authority with zero side effects
//! (audit remediation Task 12).

use std::fs;
use std::path::{Path, PathBuf};
use std::process::Command;
use std::time::{SystemTime, UNIX_EPOCH};

fn temp_root() -> PathBuf {
    let nonce = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_nanos();
    let root = std::env::temp_dir().join(format!("sea-forge-cli-m10-{nonce}"));
    fs::create_dir_all(&root).unwrap();
    root
}

fn write_policy(parent: &Path) -> PathBuf {
    let path = parent.join("policy.yaml");
    fs::write(
        &path,
        r#"version: "0.1"
identity:
  source: test
  allow_unresolved: false
rules:
  - name: allow-write
    verdict: allow
    actor_role: operator
    operation_kind: write_file
    path_prefix: ""
"#,
    )
    .unwrap();
    path
}

fn write_plan(parent: &Path, template_ref: &str) -> PathBuf {
    let path = parent.join("plan.json");
    fs::write(
        &path,
        serde_json::to_vec_pretty(&serde_json::json!({
            "version": "0.2",
            "plan_id": "plan_odi",
            "case_id": "case_odi",
            "run_id": "run_odi",
            "intent_id": "int_odi",
            "items": [
                {
                    "plan_item_id": "A",
                    "name": "A",
                    "operations": [{"kind":"write_file","path":"a.txt","content_hint":"ok"}],
                    "entry_criteria": [], "exit_criteria": [],
                    "settlement_criteria": {"require_exit_zero":false,"required_artifacts":["a.txt"],"stdout_must_contain":null,"require_approval":false},
                    "item_kind":"sandboxed_task","sandbox_class":"local","parent_stage":null,
                    "markers":{"required":true,"repetition":false,"manual_activation":false},
                    "max_instances":1,"depends_on":[]
                }
            ],
            "template_ref": template_ref
        }))
        .unwrap(),
    )
    .unwrap();
    path
}

fn run_plan(root: &Path, plan: &Path, policy: &Path) -> (i32, String, String) {
    let output = Command::new(env!("CARGO_BIN_EXE_sea-forge"))
        .args([
            "run",
            "--plan",
            plan.to_str().unwrap(),
            "--policy",
            policy.to_str().unwrap(),
            "--root",
            root.to_str().unwrap(),
        ])
        .output()
        .unwrap();
    (
        output.status.code().unwrap_or(-1),
        String::from_utf8_lossy(&output.stdout).into_owned(),
        String::from_utf8_lossy(&output.stderr).into_owned(),
    )
}

/// T10.6: a production plan naming `odi_adlc_case@0.1.0` installs the
/// built-in through the source-owned installer, derives its settlement
/// criteria via `derive_from_template`, and resolves the desired-outcome
/// origin ref against the real, bundled self-model seed hash — the exact
/// same hash `sea_forge_self_model` independently reports for that seed.
#[test]
fn t10_6_production_plan_with_odi_template_resolves_real_desired_outcome() {
    let parent = temp_root();
    let root = parent.join("state");
    let policy = write_policy(&parent);
    let plan = write_plan(&parent, "odi_adlc_case@0.1.0");

    let (code, stdout, stderr) = run_plan(&root, &plan, &policy);
    assert_eq!(code, 0, "stdout: {stdout}\nstderr: {stderr}");

    // The source-owned installer materialized the pinned built-in template.
    let installed = root.join("templates/odi_adlc_case@0.1.0.yaml");
    assert!(
        installed.exists(),
        "built-in template must be installed under <root>/templates/"
    );

    // The committed settlement_criteria record carries a real desired-outcome
    // origin ref whose hash matches the actual bundled seed model hash.
    let models = sea_forge_self_model::bundled();
    let composed = sea_forge_self_model::load_composed(&models).unwrap();
    let expected_hash = composed.seed_model_ref().semantic_model_sha256.clone();

    let case_dirs: Vec<_> = fs::read_dir(root.join("cases")).unwrap().collect();
    assert_eq!(case_dirs.len(), 1);
    let case_dir = case_dirs.into_iter().next().unwrap().unwrap().path();
    let entries_path = case_dir
        .file_name()
        .map(|name| {
            root.join("ledgers")
                .join(format!("case-{}", name.to_string_lossy()))
                .join("entries.jsonl")
        })
        .unwrap();
    let text = fs::read_to_string(&entries_path).unwrap();
    let mut found_desired_outcome = false;
    for line in text.lines().filter(|l| !l.trim().is_empty()) {
        let entry: serde_json::Value = serde_json::from_str(line).unwrap();
        if entry["record_kind"] != "settlement_criteria" {
            continue;
        }
        for origin in entry["payload"]["origin_refs"].as_array().unwrap() {
            if origin["kind"] == "desired_outcome" {
                found_desired_outcome = true;
                assert_eq!(origin["sha256"], expected_hash);
                assert_ne!(origin["sha256"], "sha256:placeholder");
                assert_eq!(origin["reference"], "Desired Outcome Criterion");
            }
        }
    }
    assert!(
        found_desired_outcome,
        "expected a desired_outcome origin ref in a committed settlement_criteria record"
    );

    let _ = fs::remove_dir_all(&parent);
}

/// T10.4 (production wiring): a tampered pinned copy of `odi_adlc_case@0.1.0`
/// that points its desired-outcome reference at a concept the validated seed
/// does not recognize as a Desired Outcome Criterion is rejected before
/// authority — the run fails, and no case/run directory is ever created.
#[test]
fn t10_4_tampered_builtin_template_is_rejected_before_authority_no_side_effects() {
    let parent = temp_root();
    let root = parent.join("state");
    let policy = write_policy(&parent);
    let plan = write_plan(&parent, "odi_adlc_case@0.1.0");

    // Pre-seed a tampered pinned template BEFORE the source-owned installer
    // ever runs: the installer never overwrites existing bytes, so this
    // tampered copy is what `load_pinned` returns.
    let templates_dir = root.join("templates");
    fs::create_dir_all(&templates_dir).unwrap();
    let mut tampered = sea_forge_planner::templates::odi_adlc_case_template(
        "godspeed.adlc_odi_case",
        "sha256:not-the-real-seed-hash",
    );
    for origin in &mut tampered.origin_refs {
        origin.reference = "Not A Real Concept".into();
    }
    fs::write(
        templates_dir.join("odi_adlc_case@0.1.0.yaml"),
        serde_yaml::to_string(&tampered).unwrap(),
    )
    .unwrap();

    let (code, stdout, stderr) = run_plan(&root, &plan, &policy);
    assert_ne!(code, 0, "stdout: {stdout}\nstderr: {stderr}");
    assert!(
        stderr.contains("criteria_provenance_error")
            || stdout.contains("criteria_provenance_error"),
        "stdout: {stdout}\nstderr: {stderr}"
    );

    // No execution side effects: criteria verification fails before the
    // per-instance run/workspace allocation loop, so no run ever exists even
    // though the case's bookkeeping directory (created earlier, alongside the
    // committed `case_plan` record) does.
    let runs_dirs: Vec<_> = fs::read_dir(root.join("cases"))
        .unwrap()
        .map(|entry| entry.unwrap().path().join("runs"))
        .collect();
    for runs_dir in runs_dirs {
        assert!(
            !runs_dir.exists() || fs::read_dir(&runs_dir).unwrap().next().is_none(),
            "a rejected desired-outcome ref must leave no allocated run"
        );
    }

    let _ = fs::remove_dir_all(&parent);
}

