273	
274	pub struct CommandSweSeedTransport {
275	    argv: Vec<String>,
276	    timeout: Duration,
277	}
278	
279	impl CommandSweSeedTransport {
280	    pub fn new(argv: Vec<String>, timeout_secs: u64) -> Result<Self, ForgeError> {
281	        if argv.first().is_none_or(String::is_empty) || timeout_secs == 0 {
282	            return Err(ForgeError::Config {
283	                class: "settlement_authority_config_error",
284	                path: "<policy>".into(),
285	                message: "SWE_SEED command and positive timeout are required".into(),
286	            });
287	        }
288	        Ok(Self {
289	            argv,
290	            timeout: Duration::from_secs(timeout_secs),
291	        })
292	    }
