294	
295	impl SweSeedTransport for CommandSweSeedTransport {
296	    fn submit(&self, req: &SettlementDeclarationRequest) -> Result<SweSeedResponse, ForgeError> {
297	        use std::os::unix::process::CommandExt;
298	
299	        let mut command = Command::new(&self.argv[0]);
300	        command
301	            .args(&self.argv[1..])
302	            .env_clear()
303	            .stdin(Stdio::piped())
304	            .stdout(Stdio::piped())
305	            .stderr(Stdio::piped());
306	        // Own process group so timeout can terminate the full tree.
307	        command.process_group(0);
308	        let mut child = command.spawn().map_err(settlement_authority_unavailable)?;
309	        let mut stdin = child
310	            .stdin
311	            .take()
312	            .ok_or_else(|| settlement_authority_unavailable("SWE_SEED stdin was not piped"))?;
313	        let request = serde_json::to_vec(req)?;
314	        let stdin_done = Arc::new(AtomicBool::new(false));
315	        let stdin_flag = Arc::clone(&stdin_done);
316	        let stdin_writer = thread::spawn(move || {
317	            let result = stdin.write_all(&request).and_then(|_| stdin.flush());
318	            stdin_flag.store(true, Ordering::SeqCst);
319	            result
320	        });
321	        let stdout = child
322	            .stdout
323	            .take()
324	            .ok_or_else(|| settlement_authority_unavailable("SWE_SEED stdout was not piped"))?;
325	        let stderr = child
326	            .stderr
327	            .take()
328	            .ok_or_else(|| settlement_authority_unavailable("SWE_SEED stderr was not piped"))?;
329	        let stdout_reader = thread::spawn(move || {
330	            let mut bytes = Vec::new();
331	            stdout
332	                .take(1_048_577)
333	                .read_to_end(&mut bytes)
334	                .map(|_| bytes)
335	        });
336	        let stderr_reader = thread::spawn(move || {
337	            let mut bytes = Vec::new();
338	            stderr.take(65_537).read_to_end(&mut bytes).map(|_| bytes)
339	        });
340	        let started = Instant::now();
341	        let deadline = started + self.timeout;
342	        let status = loop {
343	            if let Some(status) = child.try_wait().map_err(settlement_authority_unavailable)? {
344	                break status;
345	            }
346	            if Instant::now() >= deadline {
347	                terminate_process_tree(&child)?;
348	                let _ = child.wait();
349	                return Err(settlement_authority_unavailable(
350	                    "SWE_SEED command timed out",
351	                ));
352	            }
353	            thread::sleep(Duration::from_millis(10));
354	        };
355	        // Require stdin completion within remaining timeout before accepting response.
356	        while !stdin_done.load(Ordering::SeqCst) {
357	            if Instant::now() >= deadline {
358	                terminate_process_tree(&child)?;
359	                let _ = child.wait();
360	                return Err(settlement_authority_unavailable(
361	                    "SWE_SEED command timed out",
362	                ));
363	            }
364	            thread::sleep(Duration::from_millis(10));
365	        }
366	        stdin_writer
367	            .join()
368	            .map_err(|_| settlement_authority_unavailable("SWE_SEED stdin writer failed"))?
369	            .map_err(settlement_authority_unavailable)?;
370	        let stdout = join_reader_within(stdout_reader, deadline, "stdout")?;
371	        let stderr = join_reader_within(stderr_reader, deadline, "stderr")?;
372	        if !status.success() || stdout.len() > 1_048_576 || stderr.len() > 65_536 {
373	            return Err(settlement_authority_unavailable(
374	                "SWE_SEED command failed or exceeded output limits",
375	            ));
376	        }
377	        serde_json::from_slice(&stdout).map_err(|_| {
378	            settlement_authority_unavailable("SWE_SEED returned an invalid JSON response")
379	        })
380	    }
381	}
