383	fn terminate_process_tree(child: &std::process::Child) -> Result<(), ForgeError> {
384	    let group = format!("-{}", child.id());
385	    let group_kill = Command::new("/bin/kill")
386	        .args(["-KILL", "--", &group])
387	        .env_clear()
388	        .output()
389	        .map_err(settlement_authority_unavailable)?;
390	    if !group_kill.status.success() {
391	        let group_still_exists = Command::new("/bin/kill")
392	            .args(["-0", "--", &group])
393	            .env_clear()
394	            .output()
395	            .map_err(settlement_authority_unavailable)?
396	            .status
397	            .success();
398	        if group_still_exists {
399	            return Err(settlement_authority_unavailable(
400	                "SWE_SEED process group survived termination",
401	            ));
402	        }
403	    }
404	    Ok(())
405	}
