407	fn join_reader_within(
408	    handle: thread::JoinHandle<std::io::Result<Vec<u8>>>,
409	    deadline: Instant,
410	    label: &str,
411	) -> Result<Vec<u8>, ForgeError> {
412	    loop {
413	        if handle.is_finished() {
414	            return handle
415	                .join()
416	                .map_err(|_| {
417	                    settlement_authority_unavailable(format!("SWE_SEED {label} reader failed"))
418	                })?
419	                .map_err(settlement_authority_unavailable);
420	        }
421	        if Instant::now() >= deadline {
422	            return Err(settlement_authority_unavailable(
423	                "SWE_SEED command timed out",
424	            ));
425	        }
426	        thread::sleep(Duration::from_millis(10));
427	    }
