539	/// Integrity checks shared by all adapters (spec §7.2.1).
540	fn check_integrity(req: &SettlementDeclarationRequest) -> Result<(), ForgeError> {
541	    if req.criteria_declared_at > req.execution_started_at {
542	        return Err(ForgeError::Plan {
543	            class: "settlement_integrity_error",
544	            message: "criteria_declared_at follows execution_started_at (post-hoc criteria)".into(),
545	        });
546	    }
547	    if req.declarer.actor_id == req.acting_entity_id {
548	        return Err(ForgeError::Plan {
549	            class: "settlement_integrity_error",
550	            message: "declarer is the acting entity (self-declaration)".into(),
551	        });
552	    }
553	    if req.criteria_ref.is_empty() {
554	        return Err(ForgeError::Plan {
555	            class: "settlement_integrity_error",
556	            message: "missing criteria_ref (legacy_unattributed_criteria)".into(),
557	        });
558	    }
559	    if req.origin_refs.is_empty() {
560	        return Err(ForgeError::Plan {
561	            class: "settlement_integrity_error",
562	            message: "missing origin_refs".into(),
563	        });
564	    }
565	    Ok(())
566	}
