568	/// Fixed-point weight: attribution_confidence * (1 - gaming_exposure) * (1 - hidden_debt_blindness).
569	/// Uses i64 millionths internally, clamped to [0, 1_000_000].
570	fn compute_weight(conf: &str, exposure: &str, blindness: &str) -> String {
571	    let c = parse_fixed(conf).unwrap_or(0);
572	    let e = parse_fixed(exposure).unwrap_or(0);
573	    let b = parse_fixed(blindness).unwrap_or(0);
574	    let weight = c * (1_000_000 - e) / 1_000_000 * (1_000_000 - b) / 1_000_000;
575	    format_fixed(weight.clamp(0, 1_000_000))
576	}
577	
578	/// Parse a fixed-scale decimal string ("0.800000") into millionths (800000).
579	fn parse_fixed(s: &str) -> Result<i64, ()> {
580	    let s = s.trim();
581	    let (sign, rest) = if let Some(stripped) = s.strip_prefix('-') {
582	        (-1, stripped)
583	    } else {
584	        (1, s)
585	    };
586	    let parts: Vec<&str> = rest.split('.').collect();
587	    let int_part: i64 = parts
588	        .first()
589	        .filter(|p| !p.is_empty())
590	        .map(|p| p.parse::<i64>().unwrap_or(0))
591	        .unwrap_or(0);
592	    let frac_part = parts.get(1).unwrap_or(&"");
593	    let frac_padded = format!("{:0<6}", &frac_part[..frac_part.len().min(6)]);
594	    let frac: i64 = frac_padded.parse().unwrap_or(0);
595	    Ok(sign * (int_part * 1_000_000 + frac))
596	}
597	
598	/// Format millionths (800000) as a fixed-scale decimal string ("0.800000").
599	fn format_fixed(v: i64) -> String {
600	    let sign = if v < 0 { "-" } else { "" };
601	    let abs = v.unsigned_abs();
602	    format!("{}{}.{:06}", sign, abs / 1_000_000, abs % 1_000_000)
603	}
