608	
609	    #[test]
610	    fn fixed_point_roundtrip() {
611	        assert_eq!(parse_fixed("0.800000").unwrap(), 800_000);
612	        assert_eq!(parse_fixed("1.000000").unwrap(), 1_000_000);
613	        assert_eq!(parse_fixed("0.000000").unwrap(), 0);
614	        assert_eq!(format_fixed(800_000), "0.800000");
615	        assert_eq!(format_fixed(1_000_000), "1.000000");
616	    }
617	
618	    #[test]
619	    fn weight_high_confidence_low_exposure() {
620	        let w = compute_weight("0.950000", "0.050000", "0.100000");
621	        let v = parse_fixed(&w).unwrap();
622	        // 0.95 * 0.95 * 0.90 = 0.812250 → 812250
623	        assert!(v >= 800_000, "expected weight >= 0.8, got {w}");
624	    }
625	
