627	    fn weight_high_exposure_reduces() {
628	        let w = compute_weight("0.950000", "0.800000", "0.100000");
629	        let v = parse_fixed(&w).unwrap();
630	        // 0.95 * 0.20 * 0.90 = 0.171 → 171000
631	        assert!(v < 200_000, "expected weight < 0.2, got {w}");
632	    }
