287	
288	    let recovery = CapabilityRecovery {
289	        required_disruptions: policy.required_disruptions.clone(),
290	        recovered_disruptions,
291	        recovery_ratio: format_fixed(recovery_ratio),
292	    };
293	
294	    // Orchestration burden
295	    let baseline_burden = qualifying_decls
296	        .iter()
297	        .filter_map(|d| d.orchestration_burden.as_deref())
298	        .max_by(|a, b| parse_fixed(a).cmp(&parse_fixed(b)));
299	    let current_burden = qualifying_decls
300	        .iter()
301	        .filter_map(|d| d.orchestration_burden.as_deref())
302	        .min_by(|a, b| parse_fixed(a).cmp(&parse_fixed(b)));
303	    let reduction = match (baseline_burden, current_burden) {
304	        (Some(b), Some(c)) => {
305	            let diff = parse_fixed(b) - parse_fixed(c);
306	            Some(format_fixed(diff))
307	        }
308	        _ => None,
309	    };
310	
311	    let orchestration = CapabilityOrchestration {
312	        baseline_burden: baseline_burden.map(|s| s.into()),
313	        current_burden: current_burden.map(|s| s.into()),
314	        reduction,
315	    };
316	
317	    // Confidence: reliability_ratio * coverage_ratio * recovery_ratio * burden_factor
318	    let denom = accepted_weight + regression_weight;
319	    let reliability_ratio = if denom == 0 {
320	        0
321	    } else {
322	        accepted_weight * SCALE / denom
323	    };
324	    let burden_factor = if policy.require_burden_reduction {
325	        match (
326	            &orchestration.baseline_burden,
327	            &orchestration.current_burden,
328	        ) {
329	            (Some(b), Some(c)) if parse_fixed(b) > parse_fixed(c) => SCALE,
330	            _ => 0,
331	        }
332	    } else {
333	        SCALE
334	    };
335	    let confidence = clamp(
336	        reliability_ratio * coverage_ratio / SCALE * recovery_ratio / SCALE * burden_factor / SCALE,
337	    );
338	
339	    // Status determination
340	    let min_total = parse_fixed(&policy.min_total_weight);
341	    let max_regression = parse_fixed(&policy.max_regression_weight);
342	    let min_conf = parse_fixed(&policy.min_confidence);
343	
344	    let meets_declarations = qualifying_decls.len() as u64 >= policy.min_declarations;
345	    let meets_total_weight = accepted_weight >= min_total;
346	    let meets_regression = regression_weight < max_regression;
347	    let meets_confidence = confidence >= min_conf;
348	    let meets_burden = !policy.require_burden_reduction || burden_factor == SCALE;
349	
350	    let mut contraction_reasons: Vec<String> = Vec::new();
351	
352	    let status = if meets_declarations
353	        && meets_total_weight
354	        && meets_regression
355	        && meets_confidence
356	        && meets_burden
357	        && coverage_ratio == SCALE
358	        && recovery_ratio == SCALE
359	    {
360	        CapabilityStatus::Proven
361	    } else if qualifying_decls.is_empty()
362	        && counts.accepted == 0
363	        && counts.rejected == 0
364	        && counts.escalated == 0
365	    {
366	        CapabilityStatus::Attempted
367	    } else if !qualifying_decls.is_empty() {
368	        CapabilityStatus::Demonstrated
369	    } else {
370	        CapabilityStatus::Attempted
371	    };
372	
373	    // Contraction detection: if we had proven/demonstrated but now don't
374	    if status == CapabilityStatus::Attempted && !qualifying_decls.is_empty() {
375	        contraction_reasons.push("reliability_below_threshold".into());
376	    }
377	    if !meets_regression && regression_weight > 0 {
378	        contraction_reasons.push("regression".into());
379	    }
380	    if coverage_ratio < SCALE && !qualifying_decls.is_empty() {
381	        contraction_reasons.push("evidence_invalidated".into());
382	    }
383	    contraction_reasons.sort();
384	    contraction_reasons.dedup();
385	
386	    // Evidence sample (≤ 10 most recent)
387	    let mut evidence_sample: Vec<CapabilityEvidenceSampleItem> = cap_envs
388	        .iter()
389	        .rev()
390	        .take(10)
391	        .map(|e| {
392	            let decl_for_env = cap_decls.iter().find(|d| d.run_id == e.run_id);
393	            CapabilityEvidenceSampleItem {
394	                run_id: e.run_id.clone(),
395	                settlement_status: format!("{:?}", e.capability_delta.result).to_lowercase(),
396	                declaration_id: decl_for_env.map(|d| d.declaration_id.clone()),
397	                weight: decl_for_env.map(|d| d.reliability.weight.clone()),
398	            }
399	        })
400	        .collect();
401	    evidence_sample.reverse();
402	
403	    // first_seen / last_seen from envelopes
404	    let first_seen = cap_envs
405	        .iter()
406	        .map(|e| e.intent.created_at.clone())
407	        .min()
408	        .unwrap_or_default();
409	    let last_seen = cap_envs
410	        .iter()
411	        .map(|e| e.intent.created_at.clone())
412	        .max()
413	        .unwrap_or_default();
414	
415	    CapabilityRecord {
416	        version: RECORD_VERSION.into(),
417	        capability_name: capability_name.into(),
418	        first_seen,
419	        last_seen,
420	        counts,
421	        status,
422	        promotion_policy_ref: policy.name.clone(),
423	        promotion_policy_sha256: policy.policy_sha256.clone(),
424	        qualifying,
425	        variation,
426	        recovery,
427	        orchestration,
428	        confidence: format_fixed(confidence),
429	        contraction_reasons,
430	        evidence_sample,
431	        rebuilt_at: rebuilt_at.into(),
432	    }
433	}
434	
435	/// Rebuild all capability records from envelopes + declarations + policy.
436	/// Writes to `.sea-forge/capabilities/<name>.json`.
437	/// Same inputs always produce byte-identical output modulo `rebuilt_at`.
438	pub fn rebuild_capability(
439	    root: &Path,
440	    capability_name: &str,
441	    policy: &CapabilityPromotionPolicy,
442	) -> Result<CapabilityRecord, ForgeError> {
443	    let envelopes = load_envelopes(&root.join(".sea-forge/capabilities.jsonl"))?;
444	    let declarations = load_declarations(&root.join(".sea-forge/settlement/declarations.jsonl"))?;
445	    let record = build_capability_record(
446	        capability_name,
447	        &envelopes,
448	        &declarations,
449	        policy,
450	        &chrono::Utc::now().to_rfc3339(),
451	    );
452	    // Write the record
453	    let dir = root.join(".sea-forge/capabilities");
454	    std::fs::create_dir_all(&dir).map_err(|e| ForgeError::io("create capability dir", e))?;
455	    let path = dir.join(format!("{capability_name}.json"));
456	    let json = serde_json::to_vec_pretty(&record)?;
457	    std::fs::write(&path, json).map_err(|e| ForgeError::io("write capability record", e))?;
458	    Ok(record)
459	}
460	
461	/// Check require_proven: deny unless the capability's rebuilt record has
462	/// status at least `proven` under the referenced promotion-policy hash.
463	/// Returns Ok(()) if proven, Err with citation otherwise.
464	pub fn require_proven(
465	    root: &Path,
466	    capability_name: &str,
467	    policy_ref: &str,
468	    policy_sha256: &str,
469	) -> Result<CapabilityRecord, ForgeError> {
470	    let policy = load_policy(root, policy_sha256)?;
471	    if policy.name != policy_ref {
472	        return Err(ForgeError::Plan {
473	            class: "settlement_integrity_error",
474	            message: format!(
475	                "policy name mismatch: expected {policy_ref}, found {}",
476	                policy.name
477	            ),
478	        });
479	    }
480	    let record = rebuild_capability(root, capability_name, &policy)?;
481	    if record.status != CapabilityStatus::Proven && record.status != CapabilityStatus::Metabolized {
482	        return Err(ForgeError::Plan {
483	            class: "settlement_integrity_error",
484	            message: format!(
485	                "require_proven denied: capability '{}' has status {:?} (not proven) under policy {} sha256:{}",
486	                capability_name, record.status, policy_ref, policy_sha256
487	            ),
488	        });
489	    }
490	    Ok(record)
491	}
492	
493	/// Load declarations from a JSONL file. Returns empty vec if file does not exist.
494	pub fn load_declarations(path: &Path) -> Result<Vec<SettlementDeclaration>, ForgeError> {
495	    if !path.exists() {
496	        return Ok(Vec::new());
497	    }
498	    let file =
499	        File::open(path).map_err(|e| ForgeError::io(format!("open {}", path.display()), e))?;
500	    let mut decls = Vec::new();
501	    for line in BufReader::new(file).lines() {
502	        let line = line.map_err(|e| ForgeError::io("read declarations", e))?;
503	        if line.trim().is_empty() {
504	            continue;
505	        }
506	        let decl: SettlementDeclaration =
507	            serde_json::from_str(&line).map_err(|e| ForgeError::Serialization(e.to_string()))?;
508	        decls.push(decl);
509	    }
510	    Ok(decls)
511	}
512	
513	/// Append a capability record to a JSONL file.
514	pub fn append_capability_record(path: &Path, record: &CapabilityRecord) -> Result<(), ForgeError> {
515	    let mut file = OpenOptions::new()
516	        .create(true)
517	        .append(true)
518	        .open(path)
519	        .map_err(|e| ForgeError::io(format!("open {}", path.display()), e))?;
520	    let mut encoded = serde_json::to_vec(record)?;
521	    encoded.push(b'\n');
522	    file.write_all(&encoded)
523	        .and_then(|_| file.flush())
524	        .map_err(|e| ForgeError::io("append capability record", e))
525	}
