23	/// Read-only view of a self-model snapshot for disclosure purposes.
24	/// The engine never touches raw graph data — only typed concept/capability
25	/// lookups (§6.2 G6, §10.3).
26	pub trait SnapshotView {
27	    /// The snapshot ID this view is backed by.
28	    fn snapshot_ref(&self) -> &str;
29	    /// Whether the snapshot is stale (any source hash drifted).
30	    fn is_stale(&self) -> bool;
31	    /// Look up a capability by name. Returns its derived status + evidence.
32	    fn capability(&self, name: &str) -> Option<CapabilityInfo>;
33	    /// List all declared capability names (for affordance queries).
34	    fn declared_capabilities(&self) -> Vec<String>;
35	    /// Look up an environment toolchain status by name.
36	    fn environment_status(&self, tool: &str) -> Option<EnvironmentInfo>;
37	}
