39	/// Derived capability info from the snapshot (§7.3, §16.1).
40	#[derive(Clone, Debug, PartialEq)]
41	pub struct CapabilityInfo {
42	    pub name: String,
43	    pub status: ClaimStatus,
44	    pub flags: ClaimFlags,
45	    pub evidence_refs: Vec<String>,
46	    pub settlement_refs: Vec<String>,
47	    pub capability_record_ref: Option<String>,
48	    pub limitations: Vec<String>,
49	}
