163	/// Derive claims from the snapshot within the permitted class boundary.
164	/// The query executor cannot touch non-permitted regions (§10.3).
165	fn derive_claims(
166	    kind: &QuestionKind,
167	    subject: &str,
168	    snapshot: &dyn SnapshotView,
169	    permitted: &[ClaimClass],
170	) -> Vec<GroundedClaim> {
171	    let mut claims = Vec::new();
172	    let snap_ref = snapshot.snapshot_ref();
173	
174	    match kind {
175	        QuestionKind::AskCapability => {
176	            if let Some(cap) = snapshot.capability(subject) {
177	                if permitted.contains(&ClaimClass::DeclaredCapability)
178	                    || permitted.contains(&ClaimClass::InstalledCapability)
179	                    || permitted.contains(&ClaimClass::DemonstratedCapability)
180	                {
181	                    claims.push(capability_claim(&cap, snap_ref));
182	                }
183	            } else {
184	                // Absent capability → unsupported (§10.2).
185	                claims.push(GroundedClaim {
186	                    claim_id: format!("claim_{}", subject),
187	                    claim_class: ClaimClass::DeclaredCapability,
188	                    subject: subject.into(),
189	                    status: ClaimStatus::Unsupported,
190	                    flags: ClaimFlags::default(),
191	                    statement: format!("{subject} is not declared in this installation"),
192	                    snapshot_ref: snap_ref.to_owned(),
193	                    evidence_refs: vec![],
194	                    settlement_refs: vec![],
195	                    capability_record_ref: None,
196	                    limitations: vec![],
197	                    authored_by: None,
198	                });
199	            }
200	        }
201	        QuestionKind::AskProjectionSupport => {
202	            if let Some(cap) = snapshot.capability(subject) {
203	                if permitted.contains(&ClaimClass::DeclaredCapability) {
204	                    claims.push(capability_claim(&cap, snap_ref));
205	                }
206	            }
207	        }
208	        QuestionKind::AskEnvironmentStatus => {
209	            if let Some(env) = snapshot.environment_status(subject) {
210	                if permitted.contains(&ClaimClass::EnvironmentStatus) {
211	                    let status = if env.available {
212	                        ClaimStatus::Available
213	                    } else {
214	                        ClaimStatus::Declared
215	                    };
216	                    let mut flags = ClaimFlags::default();
217	                    if !env.available {
218	                        flags.unavailable_in_environment = true;
219	                    }
220	                    claims.push(GroundedClaim {
221	                        claim_id: format!("claim_env_{}", subject),
222	                        claim_class: ClaimClass::EnvironmentStatus,
223	                        subject: subject.into(),
224	                        status,
225	                        flags,
226	                        statement: format!(
227	                            "{} is {}",
228	                            subject,
229	                            if env.available {
230	                                "available"
231	                            } else {
232	                                "unavailable"
233	                            }
234	                        ),
235	                        snapshot_ref: snap_ref.to_owned(),
236	                        evidence_refs: env.probe_evidence_ref.iter().cloned().collect(),
237	                        settlement_refs: vec![],
238	                        capability_record_ref: None,
239	                        limitations: vec![],
240	                        authored_by: None,
241	                    });
242	                }
243	            }
244	        }
245	        QuestionKind::AskAvailableAffordances => {
246	            if permitted.contains(&ClaimClass::DeclaredCapability) {
247	                for name in snapshot.declared_capabilities() {
248	                    if let Some(cap) = snapshot.capability(&name) {
249	                        claims.push(capability_claim(&cap, snap_ref));
250	                    }
251	                }
252	            }
253	        }
254	        // Other kinds are answered similarly; these three cover the core
255	        // conformance tests. Full coverage is additive.
256	        _ => {}
257	    }
258	    claims
259	}
260	
261	fn capability_claim(cap: &CapabilityInfo, snap_ref: &str) -> GroundedClaim {
262	    let class = match cap.status {
263	        ClaimStatus::Demonstrated | ClaimStatus::Validated => ClaimClass::DemonstratedCapability,
264	        ClaimStatus::Installed | ClaimStatus::Available => ClaimClass::InstalledCapability,
265	        _ => ClaimClass::DeclaredCapability,
266	    };
267	    let statement = format!(
268	        "{} is {}{}",
269	        cap.name,
270	        format!("{:?}", cap.status).to_lowercase(),
271	        if cap.flags.unavailable_in_environment {
272	            " (unavailable in environment)"
273	        } else {
274	            ""
275	        }
276	    );
277	    GroundedClaim {
278	        claim_id: format!("claim_{}", cap.name),
279	        claim_class: class,
280	        subject: cap.name.clone(),
281	        status: cap.status.clone(),
282	        flags: cap.flags.clone(),
283	        statement,
284	        snapshot_ref: snap_ref.to_owned(),
285	        evidence_refs: cap.evidence_refs.clone(),
286	        settlement_refs: cap.settlement_refs.clone(),
287	        capability_record_ref: cap.capability_record_ref.clone(),
288	        limitations: cap.limitations.clone(),
289	        authored_by: None,
290	    }
291	}
