            )]),
            envs: HashMap::new(),
        };
        let q = question(QuestionKind::AskCapability, "domain-rust");
        let a1 = answer_question(&q, &snap, &AllowAllPolicy, "tha_01", "2026-07-17T00:00:00Z");
        let a2 = answer_question(&q, &snap, &AllowAllPolicy, "tha_01", "2026-07-17T00:00:00Z");
        assert_eq!(a1, a2);
