    #[test]
    fn t11_7_thoth_cannot_settle_own_claim() {
        // Thoth authored a claim; it cannot settle it.
        let result = check_sod(Some("thoth"), "thoth");
        assert!(result.is_err());
        let err = result.unwrap_err();
        assert_eq!(err.class(), "sod_violation");
