1	use crate::protocol::*;
2	
3	/// Immutable actor identity Thoth stamps onto every claim it constructs
4	/// (spec-adlc-thoth §10.3, T13B). Settlement/capability boundaries compare
5	/// this against the declarer/promoter via
6	/// `sea_forge_core::types::validate_claim_authorship_sod`.
7	pub const THOTH_ACTOR_ID: &str = "thoth";
8	
9	/// Read-only view of a self-model snapshot for disclosure purposes.
10	/// The engine never touches raw graph data — only typed concept/capability
11	/// lookups (§6.2 G6, §10.3).
12	pub trait SnapshotView {
13	    /// The snapshot ID this view is backed by.
14	    fn snapshot_ref(&self) -> &str;
15	    /// Whether the snapshot is stale (any source hash drifted).
16	    fn is_stale(&self) -> bool;
17	    /// Look up a capability by name. Returns its derived status + evidence.
18	    fn capability(&self, name: &str) -> Option<CapabilityInfo>;
19	    /// List all declared capability names (for affordance queries).
20	    fn declared_capabilities(&self) -> Vec<String>;
21	    /// Look up an environment toolchain status by name.
22	    fn environment_status(&self, tool: &str) -> Option<EnvironmentInfo>;
23	    /// Resolve a previously recorded authority decision by reference, for
24	    /// `ask_why_denied` explanations. `None` when the reference is absent or
25	    /// cannot be verified — the caller must then refuse to explain (§10.3,
26	    /// T13.4). Default: no recorded-decision store available.
27	    fn recorded_authority_decision(
28	        &self,
29	        _authority_decision_ref: &str,
30	    ) -> Option<RecordedAuthorityDecision> {
31	        None
32	    }
33	}
34	
35	/// Derived capability info from the snapshot (§7.3, §16.1).
36	#[derive(Clone, Debug, PartialEq)]
37	pub struct CapabilityInfo {
38	    pub name: String,
39	    pub status: ClaimStatus,
40	    pub flags: ClaimFlags,
41	    pub evidence_refs: Vec<String>,
42	    pub settlement_refs: Vec<String>,
43	    pub capability_record_ref: Option<String>,
44	    pub limitations: Vec<String>,
45	}
46	
47	/// Environment toolchain info (§7.2).
48	#[derive(Clone, Debug, PartialEq)]
49	pub struct EnvironmentInfo {
50	    pub tool: String,
51	    pub available: bool,
52	    pub probe_evidence_ref: Option<String>,
53	}
54	
55	/// A verified, recorded authority decision resolved for `ask_why_denied`.
56	/// Only these typed fields may be disclosed — never a re-derivation of fresh
57	/// claims (§10.3, T13.4).
58	#[derive(Clone, Debug, PartialEq)]
59	pub struct RecordedAuthorityDecision {
60	    pub authority_decision_ref: String,
61	    pub denied_classes: Vec<ClaimClass>,
62	    pub reason_code: String,
63	}
64	
65	/// Disclosure policy: which actor roles may see which claim classes.
66	/// Wraps the authority surface's permit check (§8.2).
67	pub trait DisclosurePolicy {
68	    /// Returns true if `actor_role` is permitted to disclose `claim_class`.
69	    /// Absent surface ⇒ deny (§8.2, T11.8).
70	    fn permits(&self, actor_role: &str, claim_class: &ClaimClass) -> bool;
71	    /// Whether this policy requires a fresh (non-stale) snapshot.
72	    fn requires_fresh(&self) -> bool {
73	        false
74	    }
75	}
76	
77	/// The fixed authority notice.
78	const AUTHORITY_NOTICE: &str = "This answer confers no execution authority.";
79	
80	/// Resolve a question into an answer through the disclosure pipeline (§16.2).
81	///
82	/// Steps: classify → check policy → deny or plan → bounded query → claim
83	/// derivation → answer assembly. Deterministic over (question, snapshot,
84	/// policy). A required-fresh policy refuses before any bounded query method
85	/// on `snapshot` is invoked (§7.4, T13.5) — only `snapshot_ref`/`is_stale`
86	/// (metadata, not self-model content) are ever called before that gate.
87	pub fn answer_question(
88	    question: &ThothQuestion,
89	    snapshot: &dyn SnapshotView,
90	    policy: &dyn DisclosurePolicy,
91	    answer_id: &str,
92	    answered_at: &str,
93	) -> ThothAnswer {
94	    let candidates = candidate_classes(&question.kind);
95	    // Classify which candidate classes are permitted for this actor.
96	    let permitted: Vec<ClaimClass> = candidates
97	        .iter()
98	        .filter(|c| policy.permits(&question.actor_id, c))
99	        .cloned()
100	        .collect();
101	    let omitted: Vec<ClaimClass> = candidates
102	        .iter()
103	        .filter(|c| !permitted.contains(c))
104	        .cloned()
105	        .collect();
106	
107	    // If nothing is permitted, deny. Denial names classes only (§10.3).
108	    if permitted.is_empty() && !candidates.is_empty() {
109	        return ThothAnswer::denied(
110	            &question.question_id,
111	            answer_id,
112	            candidates.clone(),
113	            snapshot.snapshot_ref(),
114	            answered_at,
115	        );
116	    }
117	
118	    // ask_why_denied is handled separately — reads only a recorded decision,
119	    // never a bounded snapshot query.
120	    if question.kind == QuestionKind::AskWhyDenied {
121	        return answer_why_denied(question, snapshot, answer_id, answered_at);
122	    }
123	
124	    // Pre-query freshness gate (§7.4, T13.5): a required-fresh policy refuses
125	    // before `derive_claims` ever calls a bounded query method. Only
126	    // `is_stale` (staleness metadata, not self-model content) is consulted.
127	    if policy.requires_fresh() && snapshot.is_stale() {
128	        return ThothAnswer {
129	            answer_id: answer_id.into(),
130	            question_id: question.question_id.clone(),
131	            disposition: Disposition::Denied,
132	            claims: vec![],
133	            omitted_claim_classes: candidates,
134	            snapshot_ref: snapshot.snapshot_ref().to_owned(),
135	            freshness: Freshness::Stale,
136	            assurance: "local_tamper_evident".into(),
137	            limitations: vec!["required_fresh_snapshot_is_stale".into()],
138	            authority_notice: AUTHORITY_NOTICE.into(),
139	            answered_at: answered_at.into(),
140	        };
141	    }
142	
143	    // Bounded query: derive claims only from permitted classes.
144	    let claims = derive_claims(&question.kind, &question.subject, snapshot, &permitted);
145	    let freshness = freshness_of(snapshot);
146	    let disposition = if omitted.is_empty() {
147	        Disposition::Answered
148	    } else {
149	        Disposition::Partial
150	    };
151	
152	    ThothAnswer {
153	        answer_id: answer_id.into(),
154	        question_id: question.question_id.clone(),
155	        disposition,
156	        claims,
157	        omitted_claim_classes: omitted,
158	        snapshot_ref: snapshot.snapshot_ref().to_owned(),
159	        freshness,
160	        assurance: "local_tamper_evident".into(),
161	        limitations: vec![],
162	        authority_notice: AUTHORITY_NOTICE.into(),
163	        answered_at: answered_at.into(),
164	    }
165	}
