167	/// Explain a prior denial by resolving its recorded authority-decision
168	/// reference. Discloses only the recorded `denied_classes`/`reason_code` —
169	/// never fresh claims. Unresolvable/unverified reference ⇒ denied (§10.3,
170	/// T13.4).
171	fn answer_why_denied(
172	    question: &ThothQuestion,
173	    snapshot: &dyn SnapshotView,
174	    answer_id: &str,
175	    answered_at: &str,
176	) -> ThothAnswer {
177	    match snapshot.recorded_authority_decision(&question.subject) {
178	        Some(decision) => ThothAnswer {
179	            answer_id: answer_id.into(),
180	            question_id: question.question_id.clone(),
181	            disposition: Disposition::Answered,
182	            claims: vec![],
183	            omitted_claim_classes: decision.denied_classes,
184	            snapshot_ref: snapshot.snapshot_ref().to_owned(),
185	            freshness: freshness_of(snapshot),
186	            assurance: "local_tamper_evident".into(),
187	            limitations: vec![decision.reason_code],
188	            authority_notice: AUTHORITY_NOTICE.into(),
189	            answered_at: answered_at.into(),
190	        },
191	        None => ThothAnswer {
192	            answer_id: answer_id.into(),
193	            question_id: question.question_id.clone(),
194	            disposition: Disposition::Denied,
195	            claims: vec![],
196	            omitted_claim_classes: vec![],
197	            snapshot_ref: snapshot.snapshot_ref().to_owned(),
198	            freshness: freshness_of(snapshot),
199	            assurance: "local_tamper_evident".into(),
200	            limitations: vec!["authority_decision_ref_unresolved".into()],
201	            authority_notice: AUTHORITY_NOTICE.into(),
202	            answered_at: answered_at.into(),
203	        },
204	    }
205	}
