215	/// The permitted capability-ladder class with the lowest evidence rung, in
216	/// ladder order. Used to label facts (including absence/unsupported facts)
217	/// under the most conservative class the policy actually grants (§9.3,
218	/// T13.2, T13.3).
219	fn lowest_permitted_capability_class(permitted: &[ClaimClass]) -> Option<ClaimClass> {
220	    [
221	        ClaimClass::DeclaredCapability,
222	        ClaimClass::InstalledCapability,
223	        ClaimClass::DemonstratedCapability,
224	    ]
225	    .into_iter()
226	    .find(|c| permitted.contains(c))
227	}
228	
229	/// The evidence rung ceiling a claim class may assert (§7.3, §16.1).
230	fn capability_class_ceiling(class: &ClaimClass) -> ClaimStatus {
231	    match class {
232	        ClaimClass::DeclaredCapability => ClaimStatus::Declared,
233	        ClaimClass::InstalledCapability => ClaimStatus::Available,
234	        _ => ClaimStatus::Demonstrated,
235	    }
236	}
237	
238	/// Build a capability claim bounded to what `permitted` actually grants.
239	/// Never elevates: uses the natural class for the capability's real status
240	/// when that class is permitted; otherwise downgrades to the highest
241	/// permitted class below it, capping status to that class's evidence rung.
242	/// Missing permission caps, never elevates (§10.2, §16.1, T13.1, T13.2).
243	fn capped_capability_claim(
244	    cap: &CapabilityInfo,
245	    snap_ref: &str,
246	    permitted: &[ClaimClass],
247	) -> Option<GroundedClaim> {
248	    use ClaimClass::{DeclaredCapability, DemonstratedCapability, InstalledCapability};
249	    let natural_class = match cap.status {
250	        ClaimStatus::Demonstrated | ClaimStatus::Validated => DemonstratedCapability,
251	        ClaimStatus::Installed | ClaimStatus::Available => InstalledCapability,
252	        _ => DeclaredCapability,
253	    };
254	    let class = if permitted.contains(&natural_class) {
255	        natural_class
256	    } else if natural_class == DemonstratedCapability && permitted.contains(&InstalledCapability) {
257	        InstalledCapability
258	    } else if permitted.contains(&DeclaredCapability) {
259	        DeclaredCapability
260	    } else {
261	        lowest_permitted_capability_class(permitted)?
262	    };
263	    let ceiling = capability_class_ceiling(&class);
264	    let status = if cap.status <= ceiling {
265	        cap.status.clone()
266	    } else {
267	        ceiling
268	    };
269	    let statement = format!(
270	        "{} is {}{}",
271	        cap.name,
272	        format!("{status:?}").to_lowercase(),
273	        if cap.flags.unavailable_in_environment {
274	            " (unavailable in environment)"
275	        } else {
276	            ""
277	        }
278	    );
279	    Some(GroundedClaim {
280	        claim_id: format!("claim_{}", cap.name),
281	        claim_class: class,
282	        subject: cap.name.clone(),
283	        status,
284	        flags: cap.flags.clone(),
285	        statement,
286	        snapshot_ref: snap_ref.to_owned(),
287	        evidence_refs: cap.evidence_refs.clone(),
288	        settlement_refs: cap.settlement_refs.clone(),
289	        capability_record_ref: cap.capability_record_ref.clone(),
290	        limitations: cap.limitations.clone(),
291	        authored_by: Some(THOTH_ACTOR_ID.into()),
292	    })
293	}
294	
295	/// Build an `Unsupported`-status claim under `class`. `Unsupported` is the
296	/// floor rung (§7.3) — safe to file under any permitted class since it
297	/// asserts no positive evidence.
298	fn unsupported_claim(
299	    subject: &str,
300	    class: ClaimClass,
301	    snap_ref: &str,
302	    statement: String,
303	) -> GroundedClaim {
304	    GroundedClaim {
305	        claim_id: format!("claim_{subject}"),
306	        claim_class: class,
307	        subject: subject.into(),
308	        status: ClaimStatus::Unsupported,
309	        flags: ClaimFlags::default(),
310	        statement,
311	        snapshot_ref: snap_ref.to_owned(),
312	        evidence_refs: vec![],
313	        settlement_refs: vec![],
314	        capability_record_ref: None,
315	        limitations: vec![],
316	        authored_by: Some(THOTH_ACTOR_ID.into()),
317	    }
318	}
319	
320	/// Derive claims from the snapshot within the permitted class boundary.
321	/// The query executor cannot touch non-permitted regions (§10.3). Total over
322	/// `QuestionKind`: every reachable arm (all but `AskWhyDenied`, handled
323	/// earlier) always emits at least one claim when `permitted` is non-empty
324	/// (guaranteed by the caller's deny-all-when-empty gate), so `Answered`
325	/// never carries an unexplained empty claim set (T13.3).
326	fn derive_claims(
327	    kind: &QuestionKind,
328	    subject: &str,
329	    snapshot: &dyn SnapshotView,
330	    permitted: &[ClaimClass],
331	) -> Vec<GroundedClaim> {
332	    let mut claims = Vec::new();
333	    let snap_ref = snapshot.snapshot_ref();
334	
335	    match kind {
336	        QuestionKind::AskCapability | QuestionKind::AskProjectionSupport => {
337	            match snapshot.capability(subject) {
338	                Some(cap) => {
339	                    if let Some(claim) = capped_capability_claim(&cap, snap_ref, permitted) {
340	                        claims.push(claim);
341	                    }
342	                }
343	                None => {
344	                    if let Some(class) = lowest_permitted_capability_class(permitted) {
345	                        claims.push(unsupported_claim(
346	                            subject,
347	                            class,
348	                            snap_ref,
349	                            format!("{subject} is not declared in this installation"),
350	                        ));
351	                    }
352	                }
353	            }
354	        }
355	        QuestionKind::AskEnvironmentStatus => {
356	            if permitted.contains(&ClaimClass::EnvironmentStatus) {
357	                match snapshot.environment_status(subject) {
358	                    Some(env) => {
359	                        let status = if env.available {
360	                            ClaimStatus::Available
361	                        } else {
362	                            ClaimStatus::Declared
363	                        };
364	                        let mut flags = ClaimFlags::default();
365	                        if !env.available {
366	                            flags.unavailable_in_environment = true;
367	                        }
368	                        claims.push(GroundedClaim {
369	                            claim_id: format!("claim_env_{subject}"),
370	                            claim_class: ClaimClass::EnvironmentStatus,
371	                            subject: subject.into(),
372	                            status,
373	                            flags,
374	                            statement: format!(
375	                                "{} is {}",
376	                                subject,
377	                                if env.available {
378	                                    "available"
379	                                } else {
380	                                    "unavailable"
381	                                }
382	                            ),
383	                            snapshot_ref: snap_ref.to_owned(),
384	                            evidence_refs: env.probe_evidence_ref.iter().cloned().collect(),
385	                            settlement_refs: vec![],
386	                            capability_record_ref: None,
387	                            limitations: vec![],
388	                            authored_by: Some(THOTH_ACTOR_ID.into()),
389	                        });
390	                    }
391	                    None => {
392	                        claims.push(unsupported_claim(
393	                            subject,
394	                            ClaimClass::EnvironmentStatus,
395	                            snap_ref,
396	                            format!("{subject} environment status is unknown"),
397	                        ));
398	                    }
399	                }
400	            }
401	        }
402	        QuestionKind::AskAvailableAffordances => {
403	            if let Some(class) = lowest_permitted_capability_class(permitted) {
404	                let names = snapshot.declared_capabilities();
405	                if names.is_empty() {
406	                    claims.push(unsupported_claim(
407	                        "affordances",
408	                        class,
409	                        snap_ref,
410	                        "no declared capabilities are available in this installation".into(),
411	                    ));
412	                } else {
413	                    for name in names {
414	                        if let Some(cap) = snapshot.capability(&name) {
415	                            if let Some(claim) = capped_capability_claim(&cap, snap_ref, permitted)
416	                            {
417	                                claims.push(claim);
418	                            }
419	                        }
420	                    }
421	                }
422	            } else if let Some(class) = permitted.first().cloned() {
423	                // Identity/Architecture permitted but no capability-ladder
424	                // class granted; declare no data available rather than
425	                // silently returning nothing (§9.3, T13.3).
426	                claims.push(unsupported_claim(
427	                    "affordances",
428	                    class,
429	                    snap_ref,
430	                    "no affordance data is available for the permitted class".into(),
431	                ));
432	            }
433	        }
434	        QuestionKind::AskOperationRequirements | QuestionKind::AskAuthorityRequirements => {
435	            if permitted.contains(&ClaimClass::AuthorityRequirements) {
436	                claims.push(unsupported_claim(
437	                    subject,
438	                    ClaimClass::AuthorityRequirements,
439	                    snap_ref,
440	                    format!("no authority-requirement data is available for {subject}"),
441	                ));
442	            }
443	        }
444	        QuestionKind::AskFailureExplanation => {
445	            if permitted.contains(&ClaimClass::FailureCondition) {
446	                claims.push(unsupported_claim(
447	                    subject,
448	                    ClaimClass::FailureCondition,
449	                    snap_ref,
450	                    format!("no failure-condition data is available for {subject}"),
451	                ));
452	            }
453	        }
454	        QuestionKind::AskEvidenceForClaim => match snapshot.capability(subject) {
455	            Some(cap)
456	                if matches!(
457	                    cap.status,
458	                    ClaimStatus::Demonstrated | ClaimStatus::Validated
459	                ) =>
460	            {
461	                if let Some(claim) = capped_capability_claim(&cap, snap_ref, permitted) {
462	                    claims.push(claim);
463	                }
464	            }
465	            _ => {
466	                claims.push(unsupported_claim(
467	                    subject,
468	                    ClaimClass::DemonstratedCapability,
469	                    snap_ref,
470	                    format!("no demonstrated evidence is available for {subject}"),
471	                ));
472	            }
473	        },
474	        QuestionKind::AskWhyDenied => {
475	            unreachable!("ask_why_denied is handled in answer_question before derive_claims")
476	        }
477	    }
478	    claims
479	}
