1	//! Thoth `ask` command (spec-adlc-thoth §11.1, §8.6).
2	//!
3	//! `sea-forge ask <kind> <subject> [--purpose] [--case] [--json]`
4	//! Exit codes: 0 answered, 4 denied (governance success), 2 usage, 1 error.
5	
6	use sea_forge_core::errors::ForgeError;
7	use sea_forge_self_model::store;
8	use sea_forge_thoth::{
9	    engine::{answer_question, CapabilityInfo, DisclosurePolicy, SnapshotView},
10	    protocol::*,
11	};
12	use std::path::Path;
13	
14	/// Parse a string into a QuestionKind. Returns Err on unknown kind.
15	fn parse_kind(s: &str) -> Result<QuestionKind, ForgeError> {
16	    match s {
17	        "ask_capability" => Ok(QuestionKind::AskCapability),
18	        "ask_operation_requirements" => Ok(QuestionKind::AskOperationRequirements),
19	        "ask_authority_requirements" => Ok(QuestionKind::AskAuthorityRequirements),
20	        "ask_projection_support" => Ok(QuestionKind::AskProjectionSupport),
21	        "ask_environment_status" => Ok(QuestionKind::AskEnvironmentStatus),
22	        "ask_failure_explanation" => Ok(QuestionKind::AskFailureExplanation),
23	        "ask_evidence_for_claim" => Ok(QuestionKind::AskEvidenceForClaim),
24	        "ask_available_affordances" => Ok(QuestionKind::AskAvailableAffordances),
25	        "ask_why_denied" => Ok(QuestionKind::AskWhyDenied),
26	        _ => Err(ForgeError::Input(format!("unknown question kind: {s}"))),
27	    }
28	}
29	
30	/// Map a ClaimClass to its policy-surface string name.
31	fn class_to_str(c: &ClaimClass) -> &'static str {
32	    match c {
33	        ClaimClass::Identity => "identity",
34	        ClaimClass::Architecture => "architecture",
35	        ClaimClass::DeclaredCapability => "declared_capability",
36	        ClaimClass::InstalledCapability => "installed_capability",
37	        ClaimClass::DemonstratedCapability => "demonstrated_capability",
38	        ClaimClass::AuthorityRequirements => "authority_requirements",
39	        ClaimClass::EnvironmentStatus => "environment_status",
40	        ClaimClass::FailureCondition => "failure_condition",
41	        ClaimClass::SecurityImplementation => "security_implementation",
42	        ClaimClass::CustomerPrivate => "customer_private",
43	        ClaimClass::CredentialBearing => "credential_bearing",
44	        ClaimClass::PolicyThresholds => "policy_thresholds",
45	    }
46	}
47	
48	/// A SnapshotView backed by the self-model store. Currently returns a minimal
49	/// view — real capability data requires joining the self-model composed model
50	/// with the ledger's CapabilityRecords (additive as the self-model matures).
51	struct SelfModelSnapshotView {
52	    snapshot_ref: String,
53	    stale: bool,
54	}
55	
56	impl SnapshotView for SelfModelSnapshotView {
57	    fn snapshot_ref(&self) -> &str {
58	        &self.snapshot_ref
59	    }
60	    fn is_stale(&self) -> bool {
61	        self.stale
62	    }
63	    fn capability(&self, _name: &str) -> Option<CapabilityInfo> {
64	        // ponytail: no capability data yet; the self-model composed model
65	        // join with ledger CapabilityRecords is additive. Queries about
66	        // specific capabilities return None → unsupported.
67	        None
68	    }
69	    fn declared_capabilities(&self) -> Vec<String> {
70	        vec![]
71	    }
72	    fn environment_status(&self, _tool: &str) -> Option<sea_forge_thoth::engine::EnvironmentInfo> {
73	        None
74	    }
75	}
76	
77	/// A DisclosurePolicy backed by the authority surface.
78	struct SurfacePolicy<'a> {
79	    surface: &'a sea_forge_authority::SelfDisclosureSurface,
80	}
81	
82	impl DisclosurePolicy for SurfacePolicy<'_> {
83	    fn permits(&self, actor_id: &str, class: &ClaimClass) -> bool {
84	        // Map actor_id to role — for now use the actor_id directly.
85	        // The surface stores actor_role strings; the CLI --actor flag carries
86	        // the role.
87	        self.surface.permits(actor_id, class_to_str(class))
88	    }
89	}
90	
91	/// Run the `ask` command. Returns exit code.
92	pub fn run(
93	    kind_str: &str,
94	    subject: &str,
95	    purpose: &str,
96	    case_id: Option<&str>,
97	    json: bool,
98	    root: &Path,
99	    actor: &str,
100	) -> Result<u8, ForgeError> {
101	    let kind = parse_kind(kind_str).map_err(|e| {
102	        eprintln!("sea-forge ask: {e}");
103	        e
104	    })?;
105	
106	    // Load the current self-model snapshot for the snapshot ref.
107	    store::validate(root)?;
108	    let snapshot = store::current_snapshot(root)?.ok_or_else(|| {
109	        ForgeError::SelfModel("no self-model snapshot; run 'sea-forge self-model rebuild'".into())
110	    })?;
111	    let view = SelfModelSnapshotView {
112	        snapshot_ref: snapshot.snapshot_id.clone(),
113	        stale: store::is_stale(root)?,
114	    };
115	
116	    // Load the authority policy bundle's self_disclosure surface.
117	    let policy_path = root.join("authority/active-policy.json");
118	    let surface = if policy_path.exists() {
119	        let text = std::fs::read_to_string(&policy_path)
120	            .map_err(|e| ForgeError::io("read authority policy", e))?;
121	        let bundle: sea_forge_authority::AuthorityPolicyBundle =
122	            serde_json::from_str(&text).map_err(|e| ForgeError::Serialization(e.to_string()))?;
