473	/// Check require_proven: deny unless the capability's rebuilt record has
474	/// status at least `proven` under the referenced promotion-policy hash.
475	/// Returns Ok(()) if proven, Err with citation otherwise.
476	pub fn require_proven(
477	    root: &Path,
478	    capability_name: &str,
479	    policy_ref: &str,
480	    policy_sha256: &str,
481	) -> Result<CapabilityRecord, ForgeError> {
482	    let policy = load_policy(root, policy_sha256)?;
483	    if policy.name != policy_ref {
484	        return Err(ForgeError::Plan {
485	            class: "settlement_integrity_error",
486	            message: format!(
487	                "policy name mismatch: expected {policy_ref}, found {}",
488	                policy.name
489	            ),
490	        });
491	    }
492	    let record = rebuild_capability(root, capability_name, &policy)?;
493	    if record.status != CapabilityStatus::Proven && record.status != CapabilityStatus::Metabolized {
494	        return Err(ForgeError::Plan {
495	            class: "settlement_integrity_error",
496	            message: format!(
497	                "require_proven denied: capability '{}' has status {:?} (not proven) under policy {} sha256:{}",
498	                capability_name, record.status, policy_ref, policy_sha256
499	            ),
500	        });
501	    }
502	    Ok(record)
503	}
