505	/// Load declarations from a JSONL file. Returns empty vec if file does not exist.
506	pub fn load_declarations(path: &Path) -> Result<Vec<SettlementDeclaration>, ForgeError> {
507	    if !path.exists() {
508	        return Ok(Vec::new());
509	    }
510	    let file =
511	        File::open(path).map_err(|e| ForgeError::io(format!("open {}", path.display()), e))?;
512	    let mut decls = Vec::new();
513	    for line in BufReader::new(file).lines() {
514	        let line = line.map_err(|e| ForgeError::io("read declarations", e))?;
515	        if line.trim().is_empty() {
516	            continue;
517	        }
518	        let decl: SettlementDeclaration =
519	            serde_json::from_str(&line).map_err(|e| ForgeError::Serialization(e.to_string()))?;
520	        decls.push(decl);
521	    }
522	    Ok(decls)
523	}
