526	pub fn append_capability_record(path: &Path, record: &CapabilityRecord) -> Result<(), ForgeError> {
527	    let mut file = OpenOptions::new()
528	        .create(true)
529	        .append(true)
530	        .open(path)
531	        .map_err(|e| ForgeError::io(format!("open {}", path.display()), e))?;
532	    let mut encoded = serde_json::to_vec(record)?;
