696	    pub fn validate(&self) -> Result<(), ForgeError> {
697	        if self.mode != "deny-by-default" {
698	            return Err(schema(
699	                "self_disclosure.mode must be deny-by-default".into(),
700	            ));
701	        }
702	        for grant in &self.grants {
