73	version: "0.1"

1	#![forbid(unsafe_code)]
2	
3	//! SEA Forge concurrent case server (spec-full §10.3, §11.1, M3).
4	//!
5	//! The server listens on a Unix domain socket, accepts NDJSON requests,
6	//! and dispatches case runs as subprocesses (`sea-forge run --plan ...`)
7	//! via `spawn_blocking`. Kernel logic stays synchronous; Tokio lives only
8	//! here.
9	
10	use chrono::Utc;
11	use sea_forge_authority::{AuthorityEvaluation, AuthorityPolicyBundle, PolicyAuthorityEngine};
12	use sea_forge_core::{
13	    errors::ForgeError,
14	    ids::{case_id, random_id, run_id, valid_run_id},
15	    types::{
16	        Actor, ActorRole, AuthorityAction, CasePlan, DelegationTermination, SettlementEvent,
17	        SettlementStatus, TranscriptEvidence, TranscriptSummary, Verdict,
18	    },
19	};
20	use sea_forge_ledger::LedgerStream;
21	use serde::{Deserialize, Serialize};
22	use std::collections::HashMap;
23	use std::path::Path;
24	use std::process::Stdio;
25	use std::sync::{
26	    atomic::{AtomicBool, Ordering},
27	    Arc,
28	};
29	use tokio::io::{AsyncBufReadExt, AsyncWriteExt, BufReader};
30	use tokio::net::{UnixListener, UnixStream};
31	use tokio::process::Command;
32	use tokio::sync::{Mutex, Semaphore};
33	
34	pub mod agent_probe;
35	pub mod case_dispatch;
36	pub mod config;
37	pub mod delegation;
38	
39	pub use config::ServerConfig;
40	
41	/// A running case submitted to the server.
42	#[derive(Clone, Debug, Serialize, Deserialize)]
43	pub struct CaseEntry {
44	    pub case_id: String,
45	    pub state: String,
46	    pub exit_code: Option<i32>,
47	    pub run_dir: Option<String>,
48	}
49	
50	/// Shared server state.
51	pub struct ServerState {
52	    pub config: ServerConfig,
53	    pub cases: Mutex<HashMap<String, CaseEntry>>,
54	    delegations: Mutex<HashMap<String, DelegationHandle>>,
55	    pub(crate) permission_broker: delegation::AcpApprovalBroker,
56	    pub semaphore: Arc<Semaphore>,
57	}
58	
59	#[derive(Clone)]
60	struct DelegationHandle {
61	    case_id: String,
62	    cancel: Arc<AtomicBool>,
63	    requested: Arc<AtomicBool>,
64	}
65	
66	#[derive(Serialize)]
67	struct RecoveredDelegationEvidence<'a> {
68	    #[serde(flatten)]
69	    evidence: &'a TranscriptEvidence,
70	    case_id: &'a str,
71	    item_id: &'a str,
72	}
73	
74	#[derive(Serialize)]
75	struct RecoveredDelegationSettlement<'a> {
76	    #[serde(flatten)]
77	    settlement: &'a SettlementEvent,
78	    case_id: &'a str,
79	    item_id: &'a str,
80	}
81	
82	#[derive(Serialize)]
83	struct RecoveredAcpSession<'a> {
84	    version: &'static str,
85	    case_id: &'a str,
86	    run_id: &'a str,
87	    plan_item_id: &'a str,
88	    endpoint_ref: &'a str,
89	    continuation_key: &'a str,
90	    protocol_version: u32,
91	}
92	
93	impl ServerState {
94	    pub fn new(config: ServerConfig) -> Result<Self, ForgeError> {
95	        recover_cancelled_delegations(&config)?;
96	        let max = config.max_concurrent_runs.max(1);
97	        Ok(Self {
98	            config,
99	            cases: Mutex::new(HashMap::new()),
100	            delegations: Mutex::new(HashMap::new()),
101	            permission_broker: delegation::AcpApprovalBroker::default(),
102	            semaphore: Arc::new(Semaphore::new(max)),
103	        })
104	    }
105	
106	    /// Reload config defensively between dispatches (§8.4).
107	    pub fn reload_config(&self) -> Result<ServerConfig, String> {
108	        match ServerConfig::load(&self.config.root.join("server.yaml")) {
109	            Ok(new_config) => Ok(new_config),
110	            Err(e) => Err(e),
111	        }
112	    }
113	
114	    pub(crate) async fn begin_planned_delegation(
115	        &self,
116	        case_id: String,
117	        run_id: String,
118	    ) -> Result<Arc<AtomicBool>, ForgeError> {
119	        let cancel = Arc::new(AtomicBool::new(false));
120	        let handle = DelegationHandle {
121	            case_id,
122	            cancel: Arc::clone(&cancel),
123	            requested: Arc::new(AtomicBool::new(false)),
124	        };
125	        if self
126	            .delegations
127	            .lock()
128	            .await
129	            .insert(run_id, handle)
130	            .is_some()
131	        {
132	            return Err(ForgeError::Input("delegation run_id already active".into()));
133	        }
134	        Ok(cancel)
135	    }
136	
137	    pub(crate) async fn end_delegation(&self, run_id: &str) {
138	        self.delegations.lock().await.remove(run_id);
139	    }
140	}
141	
142	/// Recover a cancellation whose control record committed before server loss.
143	/// HTTP delegations are never resumed: recovery writes the sole terminal
144	/// rejected/cancelled outcome from ledger truth.
145	fn recover_cancelled_delegations(config: &ServerConfig) -> Result<(), ForgeError> {
146	    let ledgers = config.root.join("ledgers");
147	    if !ledgers.exists() {
148	        return Ok(());
149	    }
150	    for dir in std::fs::read_dir(&ledgers).map_err(|e| ForgeError::io("read ledgers", e))? {
151	        let dir = dir.map_err(|e| ForgeError::io("read ledger entry", e))?;
152	        let name = dir.file_name().to_string_lossy().into_owned();
153	        if !dir
154	            .file_type()
155	            .map_err(|e| ForgeError::io("read ledger entry type", e))?
156	            .is_dir()
157	            || !name.starts_with("case-")
158	        {
159	            continue;
160	        }
161	        let ledger = LedgerStream::open(&config.root, &name, "sea-forge-server")?;
162	        ledger.verify()?;
163	        let entries = ledger.read_entries()?;
164	        let mut terminal_runs: std::collections::HashSet<String> = entries
165	            .iter()
166	            .filter(|entry| entry.record_kind == "settlement")
167	            .filter_map(|entry| entry.payload["run_id"].as_str().map(str::to_owned))
168	            .collect();
169	        for control in entries
170	            .iter()
171	            .filter(|entry| entry.record_kind == "control_request")
172	        {
173	            let run = control
174	                .payload
175	                .get("run_id")
176	                .and_then(serde_json::Value::as_str)
177	                .ok_or_else(|| ForgeError::Input("invalid cancellation control run_id".into()))?;
178	            if terminal_runs.contains(run) {
179	                continue;
180	            }
181	            let item_id = control
182	                .payload
183	                .get("plan_item_id")
184	                .and_then(serde_json::Value::as_str)
185	                .ok_or_else(|| {
186	                    ForgeError::Input("invalid cancellation control plan_item_id".into())
187	                })?;
188	            let case_id = control
189	                .payload
190	                .get("case_id")
191	                .and_then(serde_json::Value::as_str)
192	                .ok_or_else(|| ForgeError::Input("invalid cancellation control case_id".into()))?;
193	            let plan_path = config.root.join("runs").join(run).join("plan.json");
194	            let plan: CasePlan = serde_json::from_slice(
195	                &std::fs::read(&plan_path)
196	                    .map_err(|e| ForgeError::io("read cancelled delegation plan", e))?,
197	            )?;
198	            if plan.case_id != case_id || plan.run_id != run {
199	                return Err(ForgeError::Input(
200	                    "cancelled delegation control does not match plan identity".into(),
201	                ));
202	            }
203	            let endpoint_ref = plan
204	                .items
205	                .iter()
206	                .find(|item| item.plan_item_id == item_id)
207	                .and_then(|item| item.operations.first())
208	                .and_then(|operation| match operation {
209	                    sea_forge_core::types::Operation::AgentTask { endpoint_ref, .. } => {
210	                        Some(endpoint_ref.as_str())
211	                    }
212	                    _ => None,
213	                })
214	                .ok_or_else(|| {
215	                    ForgeError::Input("cancelled delegation plan missing agent_task".into())
216	                })?;

