1	use crate::{agent_probe, delegation, DispatchOutcome, ServerState, SubmitPayload};
2	use chrono::Utc;
3	use sea_forge_authority::{AuthorityEvaluation, AuthorityPolicyBundle, PolicyAuthorityEngine};
4	use sea_forge_case_runner::{write_json, CaseRunner};
5	use sea_forge_core::{
6	    errors::ForgeError,
7	    ids,
8	    types::{
9	        Actor, ActorRole, Case, CasePlan, CaseState, ExecutionRequest, ItemKind, Operation,
10	        SettlementEvent, SettlementStatus, TraceKind, Verdict,
11	    },
12	    RECORD_VERSION,
13	};
14	use sea_forge_ledger::LedgerStream;
15	use sea_forge_planner::case_engine::{replay_case, validate_proposal, CaseAction};
16	use std::{collections::BTreeMap, fs, path::PathBuf, sync::Arc};
17	use tokio::task::JoinSet;
18	
19	struct Completion {
20	    item_id: String,
21	    instance: u32,
22	    run_id: String,
23	    settlement: SettlementEvent,
24	}
25	
26	/// Server-owned, case-local dispatch. Active tasks and their permits live only
27	/// in this function; all scheduling decisions are re-derived from case events.
28	pub(crate) async fn submit(
29	    payload: SubmitPayload,
30	    state: &Arc<ServerState>,
31	) -> Result<DispatchOutcome, ForgeError> {
32	    let _ = &payload.intent;
33	    let plan_path = payload
34	        .plan
35	        .ok_or_else(|| ForgeError::Input("submit requires a plan".into()))?;
36	    let mut plan: CasePlan = serde_json::from_slice(
37	        &fs::read(&plan_path).map_err(|e| ForgeError::io("read plan proposal", e))?,
38	    )?;
39	    validate_proposal(&mut plan)?;
40	    fs::create_dir_all(&state.config.root).map_err(|e| ForgeError::io("create state root", e))?;
41	    let root = state
42	        .config
43	        .root
44	        .canonicalize()
45	        .map_err(|e| ForgeError::io("canonicalize state root", e))?;
46	    let case_id = ids::case_id()?;
47	    plan.case_id.clone_from(&case_id);
48	    let case_dir = root.join("cases").join(&case_id);
49	    let (_runs_dir, case_events) = CaseRunner::initialize_case(&case_dir)?;
50	    let stream = LedgerStream::open(&root, format!("case-{case_id}"), &payload.entity)?;
51	    stream.commit_typed("case_plan", vec![case_id.clone()], &plan, vec![])?;
52	    let intent = sea_forge_core::types::Intent {
53	        intent_id: ids::random_id("int")?,
54	        summary: format!("Execute plan {plan_path}"),
55	        actor_id: payload.entity.clone(),
56	        process_id: payload.process.clone(),
57	        created_at: Utc::now().to_rfc3339(),
58	    };
59	    let mut case = Case {
60	        version: RECORD_VERSION.into(),
61	        case_id: case_id.clone(),
62	        intent,
63	        state: CaseState::Active,
64	        plan_ref: plan.plan_id.clone(),
65	        run_ids: vec![],
66	        stages: plan
67	            .items
68	            .iter()
69	            .filter(|item| item.item_kind == ItemKind::Stage)
70	            .map(|item| item.plan_item_id.clone())
71	            .collect(),
72	        close_reason: None,
73	        created_at: Utc::now().to_rfc3339(),
74	        closed_at: None,
75	    };
76	    write_json(&case_dir.join("case.json"), &case)?;
77	    write_json(&case_dir.join("plan.json"), &plan)?;
78	    let mut events = vec![];
79	    CaseRunner::append_event(
80	        &case_events,
81	        &stream,
82	        &mut events,
83	        TraceKind::CaseCreated,
84	        None,
85	        serde_json::json!({"case_id": case_id}),
86	    )?;
87	    let mut active = JoinSet::new();
88	
89	    'dispatch: loop {
90	        let actions = CaseRunner::next_ready_actions(&plan.items, &events);
91	        if actions.is_empty() {
92	            if active.is_empty() {
93	                return Ok(DispatchOutcome {
94	                    case_id,
95	                    state: "active",
96	                    exit_code: 5,
97	                });
98	            }
99	            let completion = active
100	                .join_next()
101	                .await
102	                .ok_or_else(|| ForgeError::Internal("missing active episode".into()))?
103	                .map_err(|error| ForgeError::Internal(format!("episode task panic: {error}")))?;
104	            record_completion(
105	                &stream,
106	                &case_id,
107	                &case_events,
108	                &mut events,
109	                &mut case,
110	                completion,
111	            )?;
112	            write_json(&case_dir.join("case.json"), &case)?;
113	            continue;
114	        }
115	        let mut dispatched = false;
116	        let mut park_human = false;
117	        for action in actions {
118	            match action {
119	                CaseAction::Enable(item) => CaseRunner::append_event(
120	                    &case_events,
121	                    &stream,
122	                    &mut events,
123	                    TraceKind::ItemEnabled,
124	                    Some(&item),
125	                    serde_json::json!({}),
126	                )?,
127	                CaseAction::AchieveMilestone(item) => CaseRunner::append_event(
128	                    &case_events,
129	                    &stream,
130	                    &mut events,
131	                    TraceKind::MilestoneAchieved,
132	                    Some(&item),
133	                    serde_json::json!({}),
134	                )?,
135	                CaseAction::CompleteCase => {
136	                    case.state = CaseState::Completed;
137	                    case.closed_at = Some(Utc::now().to_rfc3339());
138	                    CaseRunner::append_event(
139	                        &case_events,
140	                        &stream,
141	                        &mut events,
142	                        TraceKind::CaseClosed,
143	                        None,
144	                        serde_json::json!({}),
145	                    )?;
146	                    write_json(&case_dir.join("case.json"), &case)?;
147	                    return Ok(DispatchOutcome {
148	                        case_id,
149	                        state: "completed",
150	                        exit_code: 0,
151	                    });
152	                }
153	                CaseAction::TerminateCase { blocking_item } => {
154	                    while let Some(completion) = active.join_next().await {
155	                        let completion = completion.map_err(|error| {
156	                            ForgeError::Internal(format!("episode task panic: {error}"))
157	                        })?;
158	                        record_completion(
159	                            &stream,
160	                            &case_id,
161	                            &case_events,
162	                            &mut events,
163	                            &mut case,
164	                            completion,
165	                        )?;
166	                    }
167	                    case.state = CaseState::Terminated;
168	                    case.close_reason = Some(format!("required_item_failed:{blocking_item}"));
169	                    case.closed_at = Some(Utc::now().to_rfc3339());
170	                    CaseRunner::append_event(
171	                        &case_events,
172	                        &stream,
173	                        &mut events,
174	                        TraceKind::CaseTerminated,
175	                        None,
176	                        serde_json::json!({"blocking_item": blocking_item}),
177	                    )?;
178	                    write_json(&case_dir.join("case.json"), &case)?;
179	                    return Ok(DispatchOutcome {
180	                        case_id,
181	                        state: "terminated",
182	                        exit_code: 3,
183	                    });
184	                }
185	                CaseAction::ParkHumanTask(item_id) => {
186	                    CaseRunner::append_event(
187	                        &case_events,
188	                        &stream,
189	                        &mut events,
190	                        TraceKind::ItemActivated,
191	                        Some(&item_id),
192	                        serde_json::json!({"human_task": true}),
193	                    )?;
194	                    park_human = true;
195	                }
196	                CaseAction::Activate(item_id) => {
197	                    let item = plan
198	                        .items
199	                        .iter()
200	                        .find(|item| item.plan_item_id == item_id)
201	                        .ok_or_else(|| ForgeError::Internal("missing plan item".into()))?
202	                        .clone();
203	                    // The case engine emits Activate for any non-Milestone,
204	                    // non-HumanTask item without manual_activation, including
205	                    // Stage/TimerListener/UserEventListener. Only SandboxedTask
206	                    // and AgentTask have dispatch semantics; reject the rest
207	                    // with a typed error before any permit or side effect.
208	                    if !matches!(
209	                        item.item_kind,
210	                        ItemKind::SandboxedTask | ItemKind::AgentTask
211	                    ) {
212	                        return Err(ForgeError::Input(format!(
213	                            "non_executable item kind cannot be dispatched: {:?}",
214	                            item.item_kind
215	                        )));
216	                    }
217	                    let permit = if active.is_empty() {
218	                        state.semaphore.clone().acquire_owned().await.map_err(|_| {
219	                            ForgeError::Internal("server semaphore unavailable".into())
220	                        })?
221	                    } else {
222	                        tokio::select! {
223	                            biased;
224	                            completion = active.join_next() => {
225	                                let completion = completion
226	                                    .ok_or_else(|| ForgeError::Internal("missing active episode".into()))?
227	                                    .map_err(|error| ForgeError::Internal(format!("episode task panic: {error}")))?;
228	                                record_completion(&stream, &case_id, &case_events, &mut events, &mut case, completion)?;
229	                                write_json(&case_dir.join("case.json"), &case)?;
230	                                continue 'dispatch;
231	                            }
232	                            permit = state.semaphore.clone().acquire_owned() => permit
233	                                .map_err(|_| ForgeError::Internal("server semaphore unavailable".into()))?,
234	                        }
235	                    };
236	                    let projection = replay_case(&plan.items, &events);
237	                    let instance = projection
238	                        .items
239	                        .iter()
240	                        .find(|state| state.item_id == item_id)
241	                        .map_or(1, |state| state.instances + 1);
242	                    let run_id = ids::run_id()?;
243	                    CaseRunner::append_event(
244	                        &case_events,
245	                        &stream,
246	                        &mut events,
247	                        TraceKind::ItemActivated,
248	                        Some(&item_id),
249	                        serde_json::json!({
250	                            "instance": instance,
251	                            "run_id": run_id,
252	                            "episode_kind": match item.item_kind {
253	                                ItemKind::SandboxedTask => "sandboxed_task",
254	                                ItemKind::AgentTask => "agent_task",
255	                                // Validated above; the wildcard is exhaustive
256	                                // for the remaining variants and never selects.
257	                                _ => "non_executable",
258	                            },
259	                        }),
260	                    )?;
261	                    let config = state.config.clone();
262	                    let policy = payload.policy.clone();
263	                    let entity = payload.entity.clone();
264	                    let process = payload.process.clone();
265	                    let timeout = payload.timeout;
266	                    let root = root.clone();
267	                    let permission_broker = state.permission_broker.clone();
268	                    let state_for_task = Arc::clone(state);
269	                    let case_for_task = case_id.clone();
270	                    let run_for_task = run_id.clone();
271	                    active.spawn(async move {
272	                        let _permit = permit;
273	                        let criteria_ref = item.settlement_criteria_ref.clone();
274	                        let result = match item.item_kind {
275	                            ItemKind::AgentTask => {
276	                                let cancel = state_for_task
277	                                    .begin_planned_delegation(case_for_task.clone(), run_id.clone())
278	                                    .await;
279	                                let result = match cancel {
280	                                    Ok(cancel) => {
281	                                        execute_agent(
282	                                            &config,
283	                                            &item,
284	                                            &policy,
285	                                            &entity,
286	                                            &process,
287	                                            &case_for_task,
288	                                            &run_id,
289	                                            permission_broker,
290	                                            cancel,
291	                                        )
292	                                        .await
293	                                    }
294	                                    Err(error) => Err(error),
295	                                };
296	                                state_for_task.end_delegation(&run_id).await;
297	                                result
298	                            }
299	                            ItemKind::SandboxedTask => tokio::task::spawn_blocking(move || {
300	                                execute_sandbox(
301	                                    &config,
302	                                    &item,
303	                                    &policy,
304	                                    &entity,
305	                                    &process,
306	                                    &case_for_task,
307	                                    &run_for_task,
308	                                    root,
309	                                    timeout,
310	                                )
311	                            })
312	                            .await
313	                            .map_err(|e| {
314	                                ForgeError::Internal(format!("sandbox episode panic: {e}"))
315	                            })
316	                            .and_then(|result| result),
317	                            _ => Err(ForgeError::Input("unsupported executable plan item".into())),
318	                        };
319	                        let settlement = result.unwrap_or_else(|error| SettlementEvent {
320	                            version: RECORD_VERSION.into(),
321	                            settlement_id: ids::random_id("set")
322	                                .unwrap_or_else(|_| "set_dispatch_error".into()),
323	                            run_id: run_id.clone(),
324	                            status: SettlementStatus::Rejected,
325	                            basis: vec!["episode_dispatch_error".into(), error.class().into()],
326	                            review_required: false,
327	                            settled_at: Utc::now().to_rfc3339(),
328	                            criteria_ref,
329	                        });
330	                        Completion {
331	                            item_id,
332	                            instance,
333	                            run_id,
334	                            settlement,
335	                        }
336	                    });
337	                    dispatched = true;
338	                }
339	            }
340	        }
341	        if park_human {
342	            while let Some(completion) = active.join_next().await {
343	                let completion = completion.map_err(|error| {
344	                    ForgeError::Internal(format!("episode task panic: {error}"))
345	                })?;
346	                record_completion(
347	                    &stream,
348	                    &case_id,
349	                    &case_events,
350	                    &mut events,
351	                    &mut case,
352	                    completion,
353	                )?;
354	            }
355	            write_json(&case_dir.join("case.json"), &case)?;
356	            return Ok(DispatchOutcome {
357	                case_id,
358	                state: "active",
359	                exit_code: 5,
360	            });
361	        }
362	        if dispatched {
363	            // Apply exactly one returned completion before looking at persisted state again.
364	            let completion = active
365	                .join_next()
366	                .await
367	                .ok_or_else(|| ForgeError::Internal("missing active episode".into()))?
368	                .map_err(|error| ForgeError::Internal(format!("episode task panic: {error}")))?;
369	            record_completion(
370	                &stream,
371	                &case_id,
372	                &case_events,
373	                &mut events,
374	                &mut case,
375	                completion,
376	            )?;
377	            write_json(&case_dir.join("case.json"), &case)?;
378	        }
379	    }
380	}
381	
382	fn record_completion(
383	    stream: &LedgerStream,
384	    case_id: &str,
385	    case_events: &std::path::Path,
386	    events: &mut Vec<sea_forge_core::types::TraceEvent>,
387	    case: &mut Case,
388	    completion: Completion,
389	) -> Result<(), ForgeError> {
390	    stream.commit_typed(
391	        "settlement_event",
392	        vec![
393	            case_id.into(),
394	            completion.run_id.clone(),
395	            completion.settlement.settlement_id.clone(),
396	        ],
397	        &completion.settlement,
398	        vec![],
399	    )?;
400	    CaseRunner::append_event(
401	        case_events,
402	        stream,
403	        events,
404	        TraceKind::SettlementRecorded,
405	        Some(&completion.item_id),
406	        serde_json::json!({
407	            "instance": completion.instance,
408	            "run_id": completion.run_id,
409	            "status": completion.settlement.status,
410	        }),
411	    )?;
412	    CaseRunner::apply_episode_completion(
413	        case,
414	        &completion.run_id,
415	        &completion.item_id,
416	        completion.instance,
417	        &completion.settlement,
418	        case_events,
419	        stream,
420	        events,
421	    )
422	    .map(|_| ())
423	}
424	
425	#[allow(clippy::too_many_arguments)]
426	async fn execute_agent(
427	    config: &crate::ServerConfig,
428	    item: &sea_forge_core::types::PlanItem,
429	    policy: &str,
430	    entity: &str,
431	    process: &str,
432	    case_id: &str,
433	    run_id: &str,
434	    permission_broker: delegation::AcpApprovalBroker,
435	    cancel: Arc<std::sync::atomic::AtomicBool>,
436	) -> Result<SettlementEvent, ForgeError> {
437	    let Operation::AgentTask {
438	        endpoint_ref,
439	        instruction,
440	        max_turns,
441	        token_budget,
442	        ..
443	    } = &item.operations[0]
444	    else {
445	        return Err(ForgeError::Input(
446	            "agent task missing agent operation".into(),
447	        ));
448	    };
449	    let outcome = delegation::execute_with_permission_broker(
450	        config,
451	        delegation::DelegationRequest {
452	            endpoint_id: endpoint_ref,
453	            instruction,
454	            model: None,
455	            max_turns: *max_turns,
456	            token_budget: *token_budget,
457	            criteria: item.settlement_criteria.clone(),
458	            policy_path: policy,
459	            entity,
460	            process,
461	        },
462	        &agent_probe::EnvironmentCredentialResolver,
463	        delegation::DelegationEpisodeContext::planned(case_id, &item.plan_item_id, run_id),
464	        move || cancel.load(std::sync::atomic::Ordering::SeqCst),
465	        Some(permission_broker),
466	    )
467	    .await?;
468	    Ok(SettlementEvent {
469	        version: RECORD_VERSION.into(),
470	        settlement_id: ids::random_id("set")?,
471	        run_id: run_id.into(),
472	        status: outcome.settlement,
473	        basis: vec!["delegation_completed".into()],
474	        review_required: false,
475	        settled_at: Utc::now().to_rfc3339(),
476	        criteria_ref: item.settlement_criteria_ref.clone(),
477	    })
478	}
479	
480	#[allow(clippy::too_many_arguments)]
481	fn execute_sandbox(
482	    config: &crate::ServerConfig,
483	    item: &sea_forge_core::types::PlanItem,
484	    policy_path: &str,
485	    entity: &str,
486	    _process: &str,
487	    case_id: &str,
488	    run_id: &str,
489	    root: PathBuf,
490	    timeout: u64,
491	) -> Result<SettlementEvent, ForgeError> {
492	    let operation = item
493	        .operations
494	        .first()
495	        .ok_or_else(|| ForgeError::Input("sandbox task missing operation".into()))?
496	        .clone();
497	    let workspace = root
498	        .join("cases")
499	        .join(case_id)
500	        .join("runs")
501	        .join(run_id)
502	        .join("workspace");
503	    let artifacts = workspace.parent().unwrap().join("artifacts");
504	    fs::create_dir_all(&workspace).map_err(|e| ForgeError::io("create workspace", e))?;
505	    fs::create_dir_all(&artifacts).map_err(|e| ForgeError::io("create artifacts", e))?;
506	    let policy = agent_probe::resolve_policy_path(&config.root, policy_path);
507	    let bundle = AuthorityPolicyBundle::load(&policy)?;
508	    let engine = PolicyAuthorityEngine::new(bundle.clone())?;
509	    let actor = Actor {
510	        actor_id: entity.into(),
511	        role: ActorRole::Operator,
512	    };
513	    let action = sea_forge_core::types::AuthorityAction::from(&operation);
514	    let decision = engine.evaluate(AuthorityEvaluation {
515	        actor: &actor,
516	        binding: bundle.resolve_identity(entity, ActorRole::Operator),
517	        run_id,
518	        case_id,
519	        plan_item_id: &item.plan_item_id,
520	        sequence: 1,
521	        action: &action,
522	        workspace_root: &workspace,
523	        evidence_refs: vec![],
524	        artifacts_root: Some(&artifacts),
525	        timeout_secs: Some(timeout),
526	        env_keys: ["PATH", "HOME"].into_iter().map(str::to_owned).collect(),
527	        domainforge_candidate: None,
528	        environment: None,
529	    })?;
530	    let ledger = LedgerStream::open(&root, format!("case-{case_id}"), entity)?;
531	    let decision_ref = ledger.commit_typed(
532	        "authority_decision",
533	        vec![run_id.into(), item.plan_item_id.clone()],
534	        &decision,
535	        vec![],
536	    )?;
537	    let execution = if decision.verdict == Verdict::Allow {
538	        let grant = engine.grant(&decision, &decision_ref, &action, None)?;
539	        sea_forge_runtime::execute(
540	            grant,
541	            &ExecutionRequest {
542	                plan_item_id: item.plan_item_id.clone(),
543	                operation,
544	                timeout_secs: timeout,
545	                env: BTreeMap::from([
546	                    (
547	                        String::from("PATH"),
548	                        std::env::var("PATH").unwrap_or_default(),
549	                    ),
550	                    (
551	                        String::from("HOME"),
552	                        std::env::var("HOME").unwrap_or_default(),
553	                    ),
554	                ]),
555	                compensating_controls: decision.compensating_controls.clone(),
556	            },
557	            run_id,
558	            &workspace,
559	            &artifacts,
560	        )?
561	    } else {
562	        sea_forge_core::types::ExecutionResult {
563	            status: sea_forge_core::types::ExecutionStatus::SpawnFailed,
564	            exit_code: None,
565	            stdout_path: String::new(),
566	            stderr_path: String::new(),
567	            started_at: Utc::now().to_rfc3339(),
568	            finished_at: Utc::now().to_rfc3339(),
569	        }
570	    };
571	    let status = if decision.verdict == Verdict::Allow
572	        && execution.status == sea_forge_core::types::ExecutionStatus::Completed
573	        && execution.exit_code == Some(0)
574	    {
575	        SettlementStatus::Accepted
576	    } else {
577	        SettlementStatus::Rejected
578	    };
579	    Ok(SettlementEvent {
580	        version: RECORD_VERSION.into(),
581	        settlement_id: ids::random_id("set")?,
582	        run_id: run_id.into(),
583	        status,
584	        basis: vec![if decision.verdict == Verdict::Allow {
585	            "execution_completed".into()
586	        } else {
587	            "authority_denied".into()
588	        }],
589	        review_required: false,
590	        settled_at: Utc::now().to_rfc3339(),
591	        criteria_ref: item.settlement_criteria_ref.clone(),
592	    })
593	}
