            token_budget: None,
            criteria: SettlementCriteria::default(),
            policy_path: policy.to_str().unwrap(),
            entity: "operator_local",
            process: "test",
        },
        &res,
    )
    .await
    .unwrap();

    assert_eq!(
        outcome.settlement,
        sea_forge_core::types::SettlementStatus::Rejected
    );
