509	/// Start the server.
510	pub async fn run(config: ServerConfig) -> Result<(), Box<dyn std::error::Error>> {
511	    let socket_path = config.socket_path.clone();
512	    let state = Arc::new(ServerState::new(config)?);
513	
514	    // Remove stale socket.
515	    let _ = std::fs::remove_file(&socket_path);
516	
517	    let listener = UnixListener::bind(&socket_path)?;
518	
519	    // Set socket permissions to 0600 (§11.1).
520	    #[cfg(unix)]
521	    {
522	        use std::os::unix::fs::PermissionsExt;
523	        std::fs::set_permissions(&socket_path, std::fs::Permissions::from_mode(0o600))?;
524	    }
525	
526	    tracing::info!("server listening on {}", socket_path.display());
527	
528	    loop {
529	        let (stream, _) = listener.accept().await?;
530	        let state = Arc::clone(&state);
531	        tokio::spawn(async move {
532	            if let Err(e) = handle_connection(stream, state).await {
533	                tracing::warn!("connection error: {e}");
534	            }
535	        });
536	    }
537	}
