539	async fn handle_connection(
540	    stream: UnixStream,
541	    state: Arc<ServerState>,
542	) -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
543	    let (reader, mut writer) = stream.into_split();
544	    let mut reader = BufReader::new(reader);
545	    let mut line = String::new();
546	
547	    loop {
548	        line.clear();
549	        let n = reader.read_line(&mut line).await?;
550	        if n == 0 {
551	            break;
552	        }
553	        let request: Request = match serde_json::from_str(line.trim()) {
554	            Ok(r) => r,
555	            Err(e) => {
556	                let resp = serde_json::json!({"error": format!("bad request: {e}")});
557	                writer.write_all(format!("{resp}\n").as_bytes()).await?;
558	                continue;
559	            }
560	        };
561	        let response = handle_request(request, &state).await;
562	        writer.write_all(format!("{response}\n").as_bytes()).await?;
563	    }
564	    Ok(())
565	}
