            },
            settlement_criteria_ref: None,
            item_kind: ItemKind::AgentTask,
            sandbox_class: None,
            parent_stage: None,
            markers: ItemMarkers::default(),
            max_instances: 1,
            depends_on: vec![],
            environment: None,
            proposed_by: None,
        }],
        template_ref: None,
        job_contract_ref: None,
    };
    let plan_path = root.path().join("plan.json");
    fs::write(&plan_path, serde_json::to_vec(&plan).unwrap()).unwrap();

    let state = std::sync::Arc::new(
        ServerState::new(config(root.path(), endpoint(address.port()))).unwrap(),
    );
    let request: Request = serde_json::from_str(&format!(
        r#"{{"verb":"submit","plan":{:?},"policy":{:?},"entity":"operator_local","process":"test"}}"#,
        plan_path.to_str().unwrap(),
        policy_path.to_str().unwrap(),
