51	    ciphertext_path: &Path,
52	    plaintext: &[u8],
53	) -> Result<SealedTranscript, ForgeError> {
54	    let key_bytes = random_bytes::<KEY_LEN>()?;
55	    let key = Key::try_from(key_bytes.as_slice())
