57	    let cipher = XChaCha20Poly1305::new(&key);
58	    let nonce_bytes = random_bytes::<NONCE_LEN>()?;
59	    let nonce = XNonce::try_from(nonce_bytes.as_slice())
60	        .map_err(|_| ForgeError::Internal("transcript seal nonce generation failed".into()))?;
