44	/// The plan body inside a template, with `${param}` placeholders in
45	/// operation payload values and criteria values.
46	#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
47	pub struct TemplatePlan {
48	    pub items: Vec<TemplateItem>,
49	    /// Typed deterministic item expansion (§7.5 E16a). Empty by default —
50	    /// old templates are byte-compatible.
51	    #[serde(default, skip_serializing_if = "Vec::is_empty")]
52	    pub repeated: Vec<RepeatedItem>,
53	}
