59	/// One entry in a `RepeatedItem` group's typed list.
60	#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
61	pub struct RepeatEntry {
62	    /// Stable key; the expanded item's ID is `{id_prefix}_{key}`.
63	    pub key: String,
64	    /// Entry-scoped parameter overrides, merged over the template's
65	    /// resolved parameters for this entry's substitution pass only.
66	    #[serde(default)]
67	    pub params: BTreeMap<String, String>,
68	    /// Extra sentries appended to the shared body's `entry_criteria` for
69	    /// this entry only — e.g. a sequential chain references the prior
70	    /// entry's deterministic ID here.
71	    #[serde(default)]
72	    pub entry_criteria: Vec<Sentry>,
73	}
74	
75	/// Typed deterministic expansion of a shared item body into N plan items
76	/// with stable, order/key-derived IDs (§7.5 E16a slice 6.1). `item`'s
77	/// `plan_item_id` must be the empty-string sentinel — expansion derives the
78	/// real ID from `id_prefix` + each entry's `key`.
79	#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
80	pub struct RepeatedItem {
81	    pub id_prefix: String,
