                "instruction_sha256": instruction_sha256,
                "max_turns": max_turns,
                "token_budget": token_budget,
            }),
        ),
        AuthorityAction::GitCommit { paths } => (
            "git_commit",
            "git_commit",
            "working-tree".into(),
            json!({"paths":paths}),
        ),
        AuthorityAction::GithubPr {
            has_required_evidence,
