304	    let mut empty_boundary = false;
305	    for candidate in candidates {
306	        for (dimension, allowed) in &candidate.boundaries {
307	            boundaries
308	                .entry(dimension.clone())
309	                .and_modify(|current| {
310	                    current.retain(|value| allowed.contains(value));
311	                    empty_boundary |= current.is_empty();
312	                })
313	                .or_insert_with(|| allowed.clone());
314	        }
315	    }
316	    let compensating_controls: BTreeSet<String> = candidates
317	        .iter()
318	        .flat_map(|candidate| candidate.compensating_controls.iter().cloned())
319	        .collect();

