}

pub struct PlanRunOptions {
    pub plan: PathBuf,
    pub policy: PathBuf,
    pub root: PathBuf,
    pub timeout_secs: u64,
    pub entity: String,
    pub process: String,
    pub intent_summary: Option<String>,
