                .into(),
        parameters: BTreeMap::new(),
        origin_refs: vec![],
        job_contract: None,
        plan: TemplatePlan {
            items: vec![],
            repeated: vec![RepeatedItem {
                id_prefix: id_prefix.into(),
                item: agent_task_body(),
                entries,
            }],
        },
    }
}

