61	/// Accepts and answers every connection with the same canned response,
62	/// until aborted — the sequential/concurrent topologies dispatch multiple
63	/// agent-task episodes against the one stub endpoint.
64	fn stub_always(response: &'static str) -> (SocketAddr, tokio::task::JoinHandle<()>) {
65	    let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
66	    listener.set_nonblocking(true).unwrap();
67	    let address = listener.local_addr().unwrap();
68	    let listener = TcpListener::from_std(listener).unwrap();
69	    let task = tokio::spawn(async move {
70	        loop {
71	            let Ok((mut stream, _)) = listener.accept().await else {
72	                break;
73	            };
74	            tokio::spawn(async move {
75	                let mut request = vec![0_u8; 32_768];
76	                let _ = stream.read(&mut request).await;
77	                let body = response.as_bytes();
78	                let header = format!(
79	                    "HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n",
80	                    body.len()
81	                );
82	                let _ = stream.write_all(header.as_bytes()).await;
83	                let _ = stream.write_all(body).await;
84	            });
85	        }
86	    });
87	    (address, task)
88	}
